"""Edit vocabulary for the loaded-flatbed speed-bump scene.

The vocabulary exposes the three causal controls the scene was built to
demonstrate: powered truck speed, the bump's physical height, and the
cargo/deck friction pairing.  It is kept separate from the simulation so
PCVE-style edit prompts stay data-driven.
"""

from __future__ import annotations

# Locate reference common scripts and install this scene's embedded helpers.
import sys as _bundle_sys0
from pathlib import Path as _BundlePath0
_BUNDLE_SCENE = _BundlePath0(__file__).resolve().parent
_BUNDLE_SCRIPTS = _BUNDLE_SCENE.parent
_PCVE_PROJECT_ROOT = next(p for p in _BUNDLE_SCENE.parents if (p / "assets").is_dir())
if str(_BUNDLE_SCRIPTS) not in _bundle_sys0.path:
    _bundle_sys0.path.insert(0, str(_BUNDLE_SCRIPTS))

# Scene-local source bundle: installed before importing scene support modules.
import importlib.abc as _bundle_abc
import importlib.util as _bundle_util
import json as _bundle_json
import sys as _bundle_sys
from pathlib import Path as _BundlePath

_BUNDLE_SCENE = _BundlePath(__file__).resolve().parent
_BUNDLE_SCRIPTS = _BUNDLE_SCENE.parent
_BUNDLE_PROJECT = next(p for p in _BUNDLE_SCENE.parents if (p / "assets").is_dir())
if str(_BUNDLE_SCRIPTS) not in _bundle_sys.path:
    _bundle_sys.path.insert(0, str(_BUNDLE_SCRIPTS))

_BUNDLE_SOURCES = _bundle_json.loads(r"""{"pcve_project_paths": "\"\"\"Path helpers shared by standalone rigid-scene folders.\"\"\"\nfrom pathlib import Path\nimport sys\n\n\ndef project_root(anchor):\n    anchor = Path(anchor).resolve()\n    candidates = (anchor, *anchor.parents)\n    for candidate in candidates:\n        if (candidate / \"assets\").is_dir() and (candidate / \"clean_scripts\").is_dir():\n            return candidate\n    raise FileNotFoundError(f\"Cannot locate project root above {anchor}; expected assets/ and clean_scripts/\")\n\n\ndef scene_root(anchor):\n    \"\"\"Find the scene folder from argv first, then from the helper's parents.\"\"\"\n    candidates = []\n    if sys.argv and sys.argv[0] not in {\"-\", \"\"}:\n        argv_path = Path(sys.argv[0]).expanduser()\n        if not argv_path.is_absolute():\n            argv_path = Path.cwd() / argv_path\n        candidates.append(argv_path.resolve().parent)\n    anchor = Path(anchor).resolve()\n    candidates.extend(anchor.parents)\n    seen = set()\n    for candidate in candidates:\n        if candidate in seen:\n            continue\n        seen.add(candidate)\n        if any(candidate.glob(\"simulate_*.py\")) and any(candidate.glob(\"render_*.py\")):\n            return candidate\n    raise FileNotFoundError(f\"Cannot locate scene entrypoints above {anchor}\")\n", "pcve_scene_runtime": "\"\"\"Shared command-line and output contracts for PCVE scene entry points.\n\nBoth ``blender -b --python render.py -- ...`` and Python with bpy are supported.\nThis module has no Blender dependency until a renderer finishes.\n\"\"\"\n\nimport argparse\nimport hashlib\nimport json\nimport math\nimport os\nimport random\nimport shutil\nimport sys\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\n_render_args = None\n\n\ndef python_for(role: str) -> Path:\n    override = os.environ.get(\"PCVE_PHYSICS_PYTHON\" if role == \"physics\" else \"PCVE_RENDER_PYTHON\")\n    if override:\n        return Path(override).expanduser()\n    names = (\"sim/python.exe\", \"sim/bin/python\") if role == \"physics\" else (\n        \"render/Scripts/python.exe\", \"render/bin/python\")\n    for base in (ROOT / \".runtime\", ROOT.parent / \"PCVE-ElasticBench/.runtime\"):\n        for name in names:\n            if (base / name).is_file():\n                return base / name\n    if role == \"physics\":\n        # The original Linux setup activates a PyBullet conda environment and\n        # invokes Blender separately. Blender's sys.executable is not Python.\n        candidates = [ROOT.parent / \"miniconda/envs/physics/bin/python\"]\n        if os.environ.get(\"CONDA_PREFIX\"):\n            prefix = Path(os.environ[\"CONDA_PREFIX\"])\n            candidates += [prefix / \"python.exe\", prefix / \"bin/python\"]\n        for name in (\"python3\", \"python\"):\n            if shutil.which(name):\n                candidates.append(Path(shutil.which(name)))\n        for candidate in candidates:\n            if candidate.is_file() and \"blender\" not in candidate.name.lower():\n                return candidate\n    return Path(sys.executable)\n\n\ndef _add(parser, flag, **kwargs):\n    if flag not in parser._option_string_actions:\n        parser.add_argument(flag, **kwargs)\n\n\ndef implementation_hashes(directory):\n    files = list(Path(directory).glob(\"*.py\"))\n    files += [ROOT / \"clean_scripts\" / name for name in (\"pcve_scene_pipeline.py\", \"pcve_edit_dsl.py\")]\n    return {str(path.relative_to(ROOT)): hashlib.sha256(path.read_bytes()).hexdigest()\n            for path in files if path.is_file()}\n\n\ndef case_outputs(folder):\n    \"\"\"Semantic output keys used by the original suite manifests.\"\"\"\n    names = dict(video=\"video.mp4\", ground_truth=\"ground_truth_transforms.json\",\n                 scenario_metadata=\"scenario_metadata.json\", scenario_overrides=\"scenario_overrides.json\",\n                 physics=\"physics_transforms.json\", scenario_input=\"scenario_input.json\", preview=\"preview.png\")\n    return {key: str((Path(folder) / name).resolve()) for key, name in names.items()\n            if (Path(folder) / name).is_file()}\n\n\ndef add_build_arguments(parser):\n    _add(parser, \"--blender\", type=Path, help=\"Blender executable; otherwise use render Python with bpy.\")\n    _add(parser, \"--physics-python\", type=Path, default=python_for(\"physics\"))\n    _add(parser, \"--render-python\", type=Path, default=python_for(\"render\"))\n    _add(parser, \"--engine\", choices=(\"cycles\", \"eevee\"), default=\"cycles\")\n    _add(parser, \"--device\", choices=(\"auto\", \"cpu\"), default=\"auto\")\n    _add(parser, \"--preview-frame\", type=int)\n    _add(parser, \"--fps\", type=int)\n    _add(parser, \"--duration-sec\", type=float)\n    return parser\n\n\ndef render_prefix(args, script: Path) -> list[str]:\n    blender = getattr(args, \"blender\", None) or os.environ.get(\"BLENDER_BIN\")\n    render_python = Path(getattr(args, \"render_python\", python_for(\"render\")))\n    if not blender and render_python == Path(sys.executable):\n        candidates = [ROOT / \"tools/blender-3.6.23-linux-x64/blender\"]\n        if shutil.which(\"blender\"):\n            candidates.append(Path(shutil.which(\"blender\")))\n        blender = next((path for path in candidates if path.is_file()), None)\n    if blender:\n        # Blender otherwise returns success even when the Python script raises.\n        return [str(Path(blender).expanduser()), \"-b\", \"--python-exit-code\", \"1\",\n                \"--python\", str(script), \"--\"]\n    return [str(render_python), str(script)]\n\n\ndef append_render_options(command, args):\n    for name in (\"engine\", \"device\", \"preview_frame\"):\n        flag = \"--\" + name.replace(\"_\", \"-\")\n        value = getattr(args, name, None)\n        if value is not None and flag not in command:\n            command += [flag, str(value)]\n    return command\n\n\ndef parse_render_args(parser, argv=None):\n    global _render_args\n    _add(parser, \"--seed\", type=int, default=0)\n    _add(parser, \"--device\", choices=(\"auto\", \"cpu\"), default=\"auto\")\n    _add(parser, \"--preview-frame\", type=int)\n    _add(parser, \"--fps\", type=int)\n    _add(parser, \"--duration-sec\", type=float)\n    _add(parser, \"--physics-python\", type=Path, default=python_for(\"physics\"))\n    # Renderers without an engine switch currently implement Cycles only.\n    _add(parser, \"--engine\", choices=(\"cycles\",), default=\"cycles\")\n    if argv is None:\n        argv = sys.argv[sys.argv.index(\"--\") + 1:] if \"--\" in sys.argv else sys.argv[1:]\n    _render_args = parser.parse_args(argv)\n    # In the original CLI duration-sec is the real-time clip length. A scene's\n    # optional demo slow-motion preset must not silently multiply that request.\n    if \"--duration-sec\" in argv and \"--slow-motion\" not in argv and hasattr(_render_args, \"slow_motion\"):\n        _render_args.slow_motion = 1\n    random.seed(_render_args.seed)\n    return _render_args\n\n\ndef apply_physics_overrides(args, baseline):\n    \"\"\"Read the original {physics: ...} override format for scalar CLI scenes.\n\n    Bare schedule arrays remain accepted by the older timed-edit escape hatch.\n    Explicit scalar command-line values take precedence over the JSON defaults.\n    \"\"\"\n    path = getattr(args, \"scenario_overrides_json\", None)\n    if path is None:\n        return None\n    payload = json.loads(Path(path).read_text(encoding=\"utf-8\"))\n    if isinstance(payload, list):\n        return Path(path)\n    physics = payload.get(\"physics\", payload)\n    unknown = set(physics) - {*baseline, \"timed_edits\"}\n    if unknown:\n        raise ValueError(f\"Unknown physics overrides: {sorted(unknown)}\")\n    for name, value in physics.items():\n        if name != \"timed_edits\" and getattr(args, name, None) is None:\n            setattr(args, name, value)\n    if physics.get(\"timed_edits\"):\n        target = Path(args.out_dir) / \"timed_edits.json\"\n        target.parent.mkdir(parents=True, exist_ok=True)\n        target.write_text(json.dumps(physics[\"timed_edits\"], indent=2), encoding=\"utf-8\")\n        return target\n    return None\n\n\ndef _matrix(position, q):\n    x, y, z, w = q\n    return [[1-2*(y*y+z*z), 2*(x*y-z*w), 2*(x*z+y*w), position[0]],\n            [2*(x*y+z*w), 1-2*(x*x+z*z), 2*(y*z-x*w), position[1]],\n            [2*(x*z-y*w), 2*(y*z+x*w), 1-2*(x*x+y*y), position[2]],\n            [0, 0, 0, 1]]\n\n\ndef _optional_metrics(value):\n    if isinstance(value, dict):\n        return {key: _optional_metrics(item) for key, item in value.items()}\n    if isinstance(value, list):\n        return [_optional_metrics(item) for item in value]\n    if isinstance(value, float) and not math.isfinite(value):\n        return None\n    return value\n\n\ndef finalize_render_outputs(out: Path, scene_name: str, args, scene=None):\n    \"\"\"Keep scene-specific files and also publish the original PCVE filenames.\"\"\"\n    out = Path(out).resolve()\n    gt_path = out / \"ground_truth_transforms.json\"\n    if gt_path.is_file():\n        gt = json.loads(gt_path.read_text(encoding=\"utf-8\"))\n        gt.setdefault(\"scene\", scene_name)\n        gt.setdefault(\"schema_version\", 1)\n        camera = gt.setdefault(\"camera\", {})\n        camera.setdefault(\"resolution\", list(args.resolution))\n        camera.setdefault(\"sensor_width_mm\", 36.0)\n        if scene is not None and scene.camera is not None:\n            cam = scene.camera\n            camera.update(matrix_world=[list(row) for row in cam.matrix_world],\n                          sensor_width_mm=float(cam.data.sensor_width),\n                          sensor_fit=cam.data.sensor_fit)\n            if cam.data.type == \"ORTHO\":\n                camera.update(projection=\"orthographic\", ortho_scale=float(cam.data.ortho_scale))\n            else:\n                camera.update(projection=\"perspective\", lens_mm=float(cam.data.lens))\n        frames = gt.get(\"frames\", [])\n        # toy_car_bottle retains its raw simulation and render_frames as well.\n        rendered = gt.get(\"render_frames\", [])\n        for index, frame in enumerate(frames):\n            frame.setdefault(\"frame_index\", frame.get(\"frame\", index + 1))\n            frame.setdefault(\"time_sec\", frame.get(\"time\", index / gt.get(\"fps\", 24)))\n            if camera.get(\"matrix_world\") is not None:\n                frame.setdefault(\"camera_matrix_world\", camera[\"matrix_world\"])\n            if index < len(rendered):\n                for name, state in rendered[index].get(\"objects\", {}).items():\n                    raw = frame.get(\"objects\", {}).get(name, {})\n                    frame[name] = dict(raw, present=True, location=state[\"position\"],\n                                       quaternion_xyzw=state[\"quaternion_xyzw\"],\n                                       matrix_world=_matrix(state[\"position\"], state[\"quaternion_xyzw\"]))\n        gt.setdefault(\"frame_start\", 1)\n        gt.setdefault(\"frame_end\", len(frames))\n        if scene_name == \"toy_car_bottle\":\n            layout = gt[\"config\"][\"layout\"]\n            gt[\"objects\"] = {\n                \"car\": {\"object_name\": \"toy_car\", \"dimensions\": [layout[\"car_length\"], layout[\"car_width\"], layout[\"car_height\"]]},\n                \"bottle\": {\"object_name\": \"plastic_bottle\", \"radius\": layout[\"bottle_radius\"], \"height\": layout[\"bottle_height\"]},\n            }\n        # A short diagnostic clip may not contain an impact. Its unavailable\n        # post-contact quality measurements are null; poses must stay finite.\n        for container in (gt, gt.get(\"physics\", {})):\n            if \"quality\" in container:\n                container[\"quality\"] = _optional_metrics(container[\"quality\"])\n        for frame in frames:\n            matrices = [item[\"matrix_world\"] for item in frame.values()\n                        if isinstance(item, dict) and \"matrix_world\" in item\n                        and not (item.get(\"present\") is False and item[\"matrix_world\"] is None)]\n            matrices += [item for key, item in frame.items() if key.endswith(\"_matrix_world\")]\n            for matrix in matrices:\n                if matrix is None:\n                    raise ValueError(\"A present object must have a ground-truth transform\")\n                if not all(math.isfinite(value) for row in matrix for value in row):\n                    raise ValueError(\"Non-finite ground-truth transform\")\n        gt_path.write_text(json.dumps(gt, indent=2, ensure_ascii=False, allow_nan=False), encoding=\"utf-8\")\n    mode = getattr(args, \"mode\", \"preview\")\n    if mode == \"animation\":\n        stem = \"basketball_door\" if scene_name == \"home_basketball_door\" else scene_name\n        source = out / (stem + \".mp4\")\n        target = out / \"video.mp4\"\n        if source.is_file() and not (scene_name == \"uneven_ground_ball\" and getattr(args, \"label\", False)):\n            shutil.copy2(source, target)\n        if not target.is_file():\n            raise FileNotFoundError(f\"Animation did not produce {target}\")\n    refresh_alias = scene_name in (\"home_basketball_door\", \"pot_lid_drop\") or (\n        scene_name == \"toy_car_bottle\" and getattr(args, \"preview_frame\", None) is None)\n    if mode == \"preview\" and (refresh_alias or not (out / \"preview.png\").is_file()):\n        number = getattr(args, \"preview_frame\", None) or 1\n        candidates = [out / f\"preview_frame_{number:04d}.png\", out / \"first_frame.png\"]\n        candidates += sorted(out.glob(\"preview_frame_*.png\"))\n        source = next((p for p in candidates if p.is_file()), None)\n        if source is None:\n            raise FileNotFoundError(f\"Preview did not produce an image in {out}\")\n        shutil.copy2(source, out / \"preview.png\")\n\n\ndef run_renderer(main, scene_name):\n    global _render_args\n    _render_args = None\n    main()\n    if _render_args is not None:\n        import bpy\n        finalize_render_outputs(_render_args.out_dir, scene_name, _render_args, bpy.context.scene)\n", "pcve_blender_compat": "\"\"\"Small Blender 3.6/4.x API differences used by the scene renderers.\"\"\"\n\nSOCKET_NAMES = {\n    \"Coat Weight\": \"Clearcoat\", \"Coat Roughness\": \"Clearcoat Roughness\",\n    \"Specular IOR Level\": \"Specular\", \"Transmission Weight\": \"Transmission\",\n    \"Emission Color\": \"Emission\", \"Sheen Weight\": \"Sheen\",\n    \"Sheen Roughness\": \"Roughness\", \"Subsurface Weight\": \"Subsurface\",\n}\n\n\ndef shader_socket(node, name):\n    socket = node.inputs.get(name)\n    if socket is None:\n        socket = node.inputs.get(SOCKET_NAMES.get(name, name))\n    if socket is None:\n        raise KeyError(f\"{node.name}: missing shader input {name}\")\n    return socket\n\n\ndef set_shader_input(node, name, value):\n    socket = shader_socket(node, name)\n    if socket.type == \"VALUE\" and isinstance(value, (tuple, list)):\n        value = sum(value[:3]) / 3\n    socket.default_value = value\n\n\ndef eevee_engine():\n    import bpy\n    return \"BLENDER_EEVEE_NEXT\" if bpy.app.version >= (4, 2, 0) else \"BLENDER_EEVEE\"\n\n\ndef set_eevee_property(settings, name, value):\n    parts = name.split(\".\")\n    for part in parts[:-1]:\n        if not hasattr(settings, part):\n            return\n        settings = getattr(settings, part)\n    if hasattr(settings, parts[-1]):\n        setattr(settings, parts[-1], value)\n\n\ndef set_color_property(settings, name, value):\n    try:\n        setattr(settings, name, value)\n    except (TypeError, ValueError):\n        candidates = (\"Filmic\", \"Standard\") if name == \"view_transform\" else (\"Medium High Contrast\", \"None\")\n        for candidate in candidates:\n            try:\n                setattr(settings, name, candidate)\n                return\n            except (TypeError, ValueError):\n                continue\n        raise\n\n\ndef configure_cycles_device(bpy, scene, requested):\n    scene.cycles.device = \"CPU\"\n    scene.render.threads_mode = \"FIXED\"\n    scene.render.threads = 4\n    if requested == \"cpu\":\n        return \"CPU\"\n    prefs = bpy.context.preferences.addons[\"cycles\"].preferences\n    for backend in (\"OPTIX\", \"CUDA\", \"HIP\", \"METAL\"):\n        try:\n            prefs.compute_device_type = backend\n            prefs.get_devices()\n            found = [device for device in prefs.devices if device.type == backend]\n            if found:\n                for device in prefs.devices:\n                    device.use = device.type == backend\n                scene.cycles.device = \"GPU\"\n                return \"GPU\"\n        except (TypeError, RuntimeError, ValueError):\n            continue\n    return \"CPU\"\n", "pcve_legacy_scene": "\"\"\"Original batch/suite workflow for scenes backed by a scenario.json file.\"\"\"\n\nimport argparse\nimport hashlib\nimport importlib\nimport json\nimport random\nimport shutil\nimport subprocess\nimport time\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\n\nfrom pcve_scene_runtime import ROOT, add_build_arguments, append_render_options, render_prefix, implementation_hashes, case_outputs\n\nimport pcve_edit_dsl as dsl\n\n\nSCRIPTS = {\n    \"home_basketball_door\": (\"render_home_basketball_door.py\", \"simulate_home_basketball_door.py\"),\n    \"pot_lid_drop\": (\"render_pot_lid_drop.py\", \"simulate_pot_lid_drop.py\"),\n    \"toy_car_bottle\": (\"render_toy_car_bottle.py\", \"simulate_toy_car_bottle.py\"),\n}\n\n\ndef write_json(path, data):\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(data, indent=2, ensure_ascii=False, allow_nan=False), encoding=\"utf-8\")\n\n\ndef parser(scene, batch=False):\n    p = argparse.ArgumentParser(description=f\"Build {'randomized samples' if batch else 'a source/edit suite'} for {scene}.\")\n    p.add_argument(\"--out-root\", type=Path, default=ROOT / \"renders\" / (f\"batch_{scene}\" if batch else f\"pcve_{scene}_suite\"))\n    p.add_argument(\"--resolution\", nargs=2, type=int, default=[1280, 720])\n    p.add_argument(\"--fps\", type=int, default=24)\n    p.add_argument(\"--duration-sec\", type=float, default=4.0)\n    p.add_argument(\"--samples\", type=int, default=32)\n    p.add_argument(\"--engine\", choices=(\"cycles\",), default=\"cycles\")\n    p.add_argument(\"--mode\", choices=(\"preview\", \"animation\"), default=\"preview\" if batch else \"animation\")\n    p.add_argument(\"--skip-existing\", action=\"store_true\")\n    p.add_argument(\"--dry-run\", action=\"store_true\")\n    p.add_argument(\"--verbose-render\", action=\"store_true\")\n    p.add_argument(\"--simulate-only\", action=\"store_true\")\n    if batch:\n        p.add_argument(\"--count\", type=int, default=4)\n        p.add_argument(\"--start-index\", type=int, default=0)\n        p.add_argument(\"--seed-base\", type=int, default=7200)\n    else:\n        p.add_argument(\"--cases\", nargs=\"+\")\n        p.add_argument(\"--clean-stale-cases\", action=\"store_true\")\n    return add_build_arguments(p)\n\n\ndef scene_directory(scene):\n    candidates = (ROOT / \"clean_scripts\" / scene, ROOT / \"clean_scripts\" / scene)\n    for directory in candidates:\n        if directory.is_dir():\n            return directory\n    raise FileNotFoundError(f\"No scene directory found for {scene}: {candidates}\")\n\n\ndef command_for(scene, folder, args, seed, overrides):\n    render, simulate = SCRIPTS[scene]\n    directory = scene_directory(scene)\n    if args.simulate_only:\n        command = [str(args.physics_python), str(directory / simulate), \"--out\", str(folder / \"physics_transforms.json\")]\n    else:\n        command = render_prefix(args, directory / render)\n        command += [\"--out-dir\", str(folder), \"--mode\", args.mode,\n                    \"--resolution\", *map(str, args.resolution), \"--samples\", str(args.samples),\n                    \"--physics-python\", str(args.physics_python), \"--seed\", str(seed)]\n        append_render_options(command, args)\n    command += [\"--fps\", str(args.fps), \"--duration-sec\", str(args.duration_sec)]\n    if overrides is not None:\n        command += [\"--scenario-overrides-json\", str(overrides)]\n    return command\n\n\ndef run_case(scene, folder, args, seed, override):\n    folder = folder.resolve()\n    overrides = folder / \"scenario_overrides.json\" if override else None\n    command = command_for(scene, folder, args, seed, overrides)\n    if args.dry_run:\n        print(subprocess.list2cmdline(command))\n        return {\"status\": \"dry_run\"}\n    implementation = implementation_hashes(scene_directory(scene))\n    payload = dict(override=override, implementation=implementation, seed=seed, fps=args.fps,\n                   duration=args.duration_sec, mode=args.mode, samples=args.samples,\n                   resolution=args.resolution, engine=args.engine, device=args.device,\n                   preview_frame=args.preview_frame, simulation_only=args.simulate_only)\n    fp = hashlib.sha256(json.dumps(payload, sort_keys=True).encode()).hexdigest()\n    status_path = folder / \"run_status.json\"\n    required = [\"physics_transforms.json\"] if args.simulate_only else [\n        \"ground_truth_transforms.json\", \"scenario_metadata.json\",\n        \"video.mp4\" if args.mode == \"animation\" else \"preview.png\"]\n    if args.skip_existing and status_path.is_file():\n        previous = json.loads(status_path.read_text(encoding=\"utf-8\"))\n        if previous.get(\"fingerprint\") == fp and all((folder / p).is_file() for p in required):\n            return dict(previous, status=\"skipped_existing\")\n    if overrides is not None:\n        write_json(overrides, override)\n    folder.mkdir(parents=True, exist_ok=True)\n    start = time.perf_counter()\n    if args.verbose_render:\n        subprocess.run(command, check=True)\n    else:\n        with (folder / \"render.log\").open(\"w\", encoding=\"utf-8\") as log:\n            subprocess.run(command, stdout=log, stderr=subprocess.STDOUT, check=True)\n    for name in required:\n        if not (folder / name).is_file():\n            raise FileNotFoundError(folder / name)\n    status = dict(status=\"completed\", valid=True, fingerprint=fp, simulation_only=args.simulate_only,\n                  render_mode=args.mode, elapsed_sec=round(time.perf_counter() - start, 3),\n                  outputs=case_outputs(folder))\n    write_json(status_path, status)\n    return status\n\n\ndef batch_main(scene, argv=None):\n    args = parser(scene, batch=True).parse_args(argv)\n    args.out_root = args.out_root.resolve()\n    if args.count < 1 or args.start_index < 0:\n        raise ValueError(\"Count must be positive and start index nonnegative\")\n    directory = scene_directory(scene)\n    import sys\n    if str(directory.parent) not in sys.path:\n        sys.path.insert(0, str(directory.parent))\n    vocab = importlib.import_module(f\"{scene}.edit_vocab\").VOCAB\n    manifest = dict(schema_version=1, scene=scene, mode=args.mode, count=args.count,\n                    start_index=args.start_index, seed_base=args.seed_base, samples=[])\n    for offset in range(args.count):\n        index = args.start_index + offset\n        seed = args.seed_base + index\n        rng = random.Random(seed)\n        params = dict(vocab.baseline_physics)\n        for binding in vocab.sim_bindings.values():\n            if isinstance(binding, dsl.SimBinding) and isinstance(params[binding.key], (int, float)):\n                params[binding.key] *= rng.uniform(.8, 1.2)\n        folder = args.out_root / f\"sample_{index:04d}\"\n        result = run_case(scene, folder, args, seed, {\"physics\": params})\n        manifest[\"samples\"].append(dict(sample_index=index, seed=seed, params=params,\n                                         out_dir=str(folder), **result))\n        if not args.dry_run:\n            write_json(args.out_root / \"batch_manifest.json\", manifest)\n\n\ndef suite_main(scene, argv=None):\n    args = parser(scene).parse_args(argv)\n    args.out_root = args.out_root.resolve()\n    directory = scene_directory(scene)\n    import sys\n    if str(directory.parent) not in sys.path:\n        sys.path.insert(0, str(directory.parent))\n    module = importlib.import_module(f\"{scene}.edit_vocab\")\n    vocab = module.VOCAB\n    source_id = f\"{scene}_baseline\"\n    cases = list(module.EDIT_CASES)\n    if args.cases:\n        unknown = set(args.cases) - {source_id, *[name for name, _ in cases]}\n        if unknown:\n            raise ValueError(f\"Unknown cases: {sorted(unknown)}\")\n        cases = [(name, instruction) for name, instruction in cases if name in args.cases]\n    if args.clean_stale_cases and not args.dry_run:\n        keep = {source_id, *[name for name, _ in module.EDIT_CASES]}\n        for folder in (args.out_root / \"cases\").glob(\"*\"):\n            if folder.is_dir() and folder.name not in keep:\n                if not folder.resolve().is_relative_to(args.out_root):\n                    raise ValueError(f\"Unsafe case directory: {folder}\")\n                shutil.rmtree(folder)\n    manifest = dict(schema_version=3, suite_name=f\"pcve_{scene}_suite\", scene=scene,\n                    baseline_physics=vocab.baseline_physics, total_frames=round(args.fps * args.duration_sec),\n                    fps=args.fps, duration_sec=args.duration_sec, physical_duration_sec=args.duration_sec,\n                    playback_duration_sec=args.duration_sec, slow_motion=1, sample_fps=args.fps,\n                    samples=args.samples, resolution=args.resolution, source=None, edits=[])\n    path = args.out_root / \"suite_manifest.json\"\n    for index, (case_id, instruction) in enumerate([(source_id, None), *cases]):\n        folder = args.out_root / \"cases\" / case_id\n        record = dict(case_id=case_id, kind=\"edit\" if instruction else \"source\",\n                      case_dir=str(folder), seed=7300 + index, status=\"pending\")\n        override = None\n        if instruction:\n            edit = dsl.parse(instruction, vocab)\n            override = {\"physics\": dsl.to_scenario_override(edit, vocab)}\n            record.update(source_case_id=source_id, edit_dsl=instruction,\n                          edit_summary=\"Change the declared physical parameter and simulate the resulting rigid-body interaction.\",\n                          applies_from_frame=dsl.starts_at_frame(edit), prompts=dsl.make_prompts(edit, vocab),\n                          physics_diff={f\"{edit.property_name} ({edit.object_id})\": {\n                              \"from\": dsl.baseline_value_for(edit, vocab), \"to\": dsl.resolved_to_value(edit, vocab)},\n                              \"timing\": dsl.timing_diff(edit, vocab)})\n            manifest[\"edits\"].append(record)\n        else:\n            record[\"description\"] = module.DESCRIPTION\n            manifest[\"source\"] = record\n        if not args.dry_run:\n            prompts = dict(schema_version=2 if instruction else 1, **record)\n            if not instruction:\n                prompts[\"prompts\"] = module.DESCRIPTION\n            write_json(folder / \"prompts.json\", prompts)\n            write_json(path, manifest)\n        try:\n            record.update(run_case(scene, folder, args, record[\"seed\"], override))\n        except Exception:\n            record[\"status\"] = \"failed\"\n            write_json(path, manifest)\n            raise\n        if not args.dry_run:\n            write_json(path, manifest)\n", "pcve_render_quality": "\"\"\"Appearance render setup only; no simulation settings or shared project edits.\"\"\"\n\nimport sys\nfrom pathlib import Path\nsys.path.insert(0, str(Path(__file__).resolve().parents[2]))\nfrom pcve_blender_compat import (shader_socket, set_shader_input, eevee_engine, set_eevee_property, set_color_property)\ndef configure_renderer(bpy,scene,args):\n    scene.render.engine=eevee_engine() if args.engine=='eevee' else 'CYCLES'\n    if args.engine=='eevee':\n        set_eevee_property(scene.eevee, 'taa_render_samples', args.samples);set_eevee_property(scene.eevee, 'use_raytracing', False)\n        set_eevee_property(scene.eevee, 'ray_tracing_options.resolution_scale', '2');set_eevee_property(scene.eevee, 'ray_tracing_options.screen_trace_quality', 0.6)\n        set_eevee_property(scene.eevee, 'use_gtao', True);set_eevee_property(scene.eevee, 'gtao_distance', 0.2);set_eevee_property(scene.eevee, 'gtao_quality', 1.0)\n        set_eevee_property(scene.eevee, 'shadow_ray_count', 1);set_eevee_property(scene.eevee, 'shadow_step_count', 8)\n    else:\n        scene.cycles.samples=args.samples;scene.cycles.use_denoising=True;scene.cycles.max_bounces=8;scene.cycles.diffuse_bounces=4;scene.cycles.glossy_bounces=4\n        scene.cycles.adaptive_threshold=.008;scene.cycles.seed=19;scene.render.use_persistent_data=True\n        # Default 1.5 px pixel filter softens fine background detail; 1.0 keeps the\n        # scanned bookshelf textures crisp without aliasing the suspension threads.\n        scene.cycles.filter_width=1.0\n        scene.cycles.device='CPU'\n        if args.device=='auto':\n            prefs=bpy.context.preferences.addons['cycles'].preferences\n            try:\n                prefs.compute_device_type='CUDA';prefs.get_devices();available=[dev for dev in prefs.devices if dev.type=='CUDA']\n                for dev in prefs.devices:dev.use=(dev.type=='CUDA')\n                if available:\n                    scene.cycles.device='GPU';scene.cycles.denoiser='OPTIX' if any(dev.type=='OPTIX' for dev in prefs.devices) else 'OPENIMAGEDENOISE'\n                    print('[render] CUDA: '+', '.join(dev.name for dev in available),flush=True)\n            except Exception as exc:\n                scene.cycles.device='CPU';scene.cycles.denoiser='OPENIMAGEDENOISE'\n                print('[render] CPU fallback: '+str(exc),flush=True)\n        return scene.cycles.device\n    return 'GPU'\n\n\ndef configure_color(scene):\n    set_color_property(scene.view_settings, 'view_transform', 'AgX');set_color_property(scene.view_settings, 'look', 'AgX - Medium High Contrast');scene.view_settings.exposure=-.22\n\n\ndef prepare_eevee(bpy,scene,moving):\n    if scene.render.engine!=eevee_engine() or bpy.app.version<(4,2,0):return\n    for light in bpy.data.lights:light.use_shadow_jitter=False\n    scene.use_nodes=True;nodes=scene.node_tree.nodes;links=scene.node_tree.links;nodes.clear()\n    layers=nodes.new('CompositorNodeRLayers');denoise=nodes.new('CompositorNodeDenoise');denoise.use_hdr=True\n    composite=nodes.new('CompositorNodeComposite');links.new(layers.outputs['Image'],denoise.inputs['Image']);links.new(denoise.outputs['Image'],composite.inputs['Image'])\n    probe_data=bpy.data.lightprobes.new('Static room irradiance','VOLUME');probe_data.resolution_x=6;probe_data.resolution_y=4;probe_data.resolution_z=4;probe_data.bake_samples=32;probe_data.surfel_density=10\n    probe=bpy.data.objects.new('Static room irradiance',probe_data);scene.collection.objects.link(probe);probe.location=[.2,.5,1.3];probe.scale=[2.5,2.2,1.6]\n    dynamic=list(moving)\n    for obj in list(dynamic):dynamic.extend(obj.children_recursive)\n    dynamic=list(dict.fromkeys(dynamic));previous=[obj.hide_render for obj in dynamic]\n    try:\n        for obj in dynamic:obj.hide_render=True\n        bpy.context.view_layer.objects.active=probe;probe.select_set(True)\n        print('[render] Baking static room indirect light',flush=True);bpy.ops.object.lightprobe_cache_bake(subset='ALL')\n    finally:\n        for obj,hidden in zip(dynamic,previous):obj.hide_render=hidden\n", "scene_support": "", "scene_support.flatbed_speed_bump.cache_contract": "\"\"\"Compatibility contract for flatbed trajectories and renderer replays.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport hashlib,json\nfrom pathlib import Path\ndef _scene_directory():\n    scripts_root = _PCVE_ROOT / 'clean_scripts'\n    for candidate in (scripts_root / \"rigid_rigid\" / \"flatbed_speed_bump\", scripts_root / \"flatbed_speed_bump\"):\n        if candidate.is_dir():\n            return candidate\n    raise FileNotFoundError(\"Scene directory not found for flatbed_speed_bump\")\n\n\nCACHE_SCHEMA_VERSION=4\n\ndef signature(parameters):\n    import hashlib, json\n    scene_dir = _PCVE_SCENE_ROOT\n    common_dir = _PCVE_ROOT / \"clean_scripts\"\n    files = list(scene_dir.glob(\"*.py\")) + list(common_dir.glob(\"*.py\"))\n    implementation = {str(path.relative_to(_PCVE_ROOT)): hashlib.sha256(path.read_bytes()).hexdigest()\n                      for path in files if path.is_file()}\n    payload = dict(implementation=implementation, scenario=parameters)\n    return hashlib.sha256(json.dumps(payload, sort_keys=True, allow_nan=False, default=str).encode()).hexdigest()\ndef validate_cache(data,requested=None):\n    message='Incompatible flatbed physics cache: parameters, geometry or implementation changed; resimulate first.'\n    if data.get('schema_version')!=CACHE_SCHEMA_VERSION or data.get('scene')!='flatbed_speed_bump':raise ValueError(message)\n    params=data.get('simulation_parameters',{})\n    if data.get('simulation_signature')!=signature(params):raise ValueError(message)\n    for name,value in (requested or {}).items():\n        if value is not None and params.get(name)!=value:raise ValueError(message+' Mismatch: '+name)\n    count=max(2,round(params['fps']*params['duration_sec']))\n    if data.get('fps')!=params['fps'] or data.get('duration_sec')!=params['duration_sec'] or data.get('frame_end')!=count or len(data.get('frames',[]))!=count:raise ValueError(message)\n    for name,value in data['physics_parameters'].items():\n        if name in params and value!=params[name]:raise ValueError(message)\n", "scene_support.flatbed_speed_bump.import_props": "\"\"\"Import the downloaded props: containers, lamp posts, speed hump, parcels.\n\nNone of these are physics bodies except the parcels, which are the *picture* of\ncargo bodies the simulation owns; the rest never appear in the ground truth.\nThree are placed at their authored size, **unscaled**:\n\n* the containers are real 12.1 / 6.4 x 2.4 x 2.9 m boxes, turned and shifted\n  only, laid out as two rows with their long sides to the road (see\n  ``CONTAINER_LAYOUT``);\n* the lamp posts are a single uniform 1.172x, because 6.40 m is the height the\n  lighting rig was built around and a lamp post is one rigid object.\n\nThe speed hump is the one non-uniform placement in the scene, and it is not a\nprop: it is the *picture* of a collider that already exists as a sine profile in\n``scene_config``. Its three factors map the model's ramp feet onto the\ncollider's half width, its 0.103 m plateau onto the requested peak, and its\n9.92 m span onto the 8 m road. A single factor cannot do all three -- at the\nwidth factor it would be 0.083 m tall, so the truck would visibly ride 87 mm\nabove the hump it is colliding with; at the height factor it would be 16.4 m\nwide, twice the road. Nothing here is animated, so no vertex-level adapter like\n``import_truck`` is needed.\n\nMeasured from the glbs (glTF units are metres):\n\n* ``container_pack`` -- a whole depot, 29.8 x 43.2 x 8.8 m, 63 meshes, 40 ft\n  boxes at 12.06 x 2.42 x 2.92 m stacked up to three high, ground plane at\n  z = 0. Long axis along +X, so the boxes present their long sides to the road.\n* ``lamppost`` -- one 5.46 m post, arm reaching +X to x = 1.25, base at z = 0.\n* ``speed_bump`` -- one hump, 2.0 m along X (the travel direction), 9.92 m\n  along Y, plateau at z = +0.103, moulded skirt down to z = -0.208. It goes\n  flat at |x| ~ 0.60 and peaks across |x| < 0.15.\n* ``carton_box_05_closed`` -- one parcel, 31.5488 x 39.9721 x 25.8244 model\n  units, centred on x = y = 0 with its base on z = 0. Unlike the three above it\n  is scaled, by the single ``CARGO_SCALE`` factor, because it has to match a\n  box collider whose half extents the simulation owns.\n\"\"\"\n\nfrom __future__ import annotations\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\nimport sys\nfrom pathlib import Path\nsys.path.insert(0, str(_PCVE_ROOT / 'clean_scripts'))\nfrom pcve_blender_compat import (shader_socket, set_shader_input, eevee_engine, set_eevee_property, set_color_property)\n\nimport math\nfrom pathlib import Path\n\nimport bpy\nfrom mathutils import Matrix, Vector\n\nimport scene_support.flatbed_speed_bump.scene_config as cfg\n\nMODELS = _PCVE_ROOT / \"assets\" / \"models\"\nCONTAINER_PACK = MODELS / \"container_pack.glb\"\nLAMPPOST = MODELS / \"lamppost.glb\"\nSPEED_HUMP = MODELS / \"speed_bump.glb\"\n\n# --------------------------------------------------------------- container yard\n# A yard is rows, not a wall. The previous layout quarter-turned every box so\n# its 2.4 m end faced the road, then set them at a 2.5 m pitch from x = -22 to\n# +58: 66 boxes shoulder to shoulder, which from the fixed camera read as a\n# corrugated fence -- and because the only face in shot was a narrow end panel,\n# every container looked taller than it is. This layout is the other reading of\n# the same asset: long sides to the road, two rows 4.75 m apart, real gaps and\n# staggered joints. The shot now shows the 12.1 m side the model was built\n# with, ~13 boxes instead of 66, and the place reads as a depot with depth\n# rather than as a barrier.\nCONTAINER_FRONT_Y = 9.20    # road-side row centre; front face lands on y = 8.0\nCONTAINER_BACK_Y = 13.95    # second row, one bay behind, joints staggered\n# The camera stands on the -Y apron, so everything on that side is seen at a\n# grazing angle and swallows the right half of the frame as bare ground. A\n# second block fills it: same asset, same orientation, but read as a yard block\n# rather than a row -- two staggered lines 4.5 m apart, so the near line hides\n# the far one except through its gaps, which is what gives the side its depth.\n# The near line starts at x = 8 because below ~x = 5 the block falls outside the\n# right edge of the frame: from this camera the apron is only visible from about\n# 30 m ahead, and a container 10.5 m off the kerb only enters the frustum at\n# x ~ 5.\nCONTAINER_APRON_Y = -10.50      # near line, camera side of the road\nCONTAINER_APRON_BACK_Y = -15.00  # far line of the apron block\nCONTAINER_ROWS = {\n    \"front\": CONTAINER_FRONT_Y,\n    \"back\": CONTAINER_BACK_Y,\n    \"apron\": CONTAINER_APRON_Y,\n    \"apron_back\": CONTAINER_APRON_BACK_Y,\n}\nCONTAINER_HEIGHT = 2.90     # the pack's boxes are all 2.9 m tall\n# The pack ships 22 whole 40 ft boxes (12.1 x 2.4 x 2.9) and 15 whole 20 ft\n# ones (6.4 x 2.4 x 2.9); everything else in it is a cut slice. Both lengths\n# are used so the yard is not one repeated box.\n#\n# (x of centre, row, nominal length, base z). A base z of 2.9 means the box is\n# stacked on the one below: the yard stacks two high in the back row only, so\n# the height reads as depth rather than as a wall next to the road.\nCONTAINER_LAYOUT = (\n    (-21.0, \"front\", \"40\", 0.0),\n    (-8.6, \"front\", \"40\", 0.0),\n    (4.2, \"front\", \"40\", 0.0),\n    (17.0, \"front\", \"40\", 0.0),\n    # A 14 m opening instead of a box at x = 29.9: a depot has aisles between\n    # blocks, and this one also lets the back row read through it, which is the\n    # cheapest depth cue in a shot that is otherwise one long wall.\n    (43.2, \"front\", \"40\", 0.0),\n    (56.3, \"front\", \"40\", 0.0),\n    (-14.8, \"back\", \"40\", 0.0),\n    (5.6, \"back\", \"40\", 0.0),\n    (5.6, \"back\", \"40\", CONTAINER_HEIGHT),\n    (24.4, \"back\", \"40\", 0.0),\n    (44.0, \"back\", \"40\", 0.0),\n    (41.0, \"back\", \"20\", CONTAINER_HEIGHT),   # 20 ft on the end of a 40 ft\n    # The apron block: two staggered lines, starting close enough to the camera\n    # that the right-hand ground has something in the foreground. The pitch\n    # wanders between 17 and 21 m on purpose -- an exact bay would read as a\n    # generated row, and this is the side of the shot the eye lands on when it\n    # has nothing else to do. The far line's boxes land in the near line's gaps.\n    (8.0, \"apron\", \"40\", 0.0),\n    (26.0, \"apron\", \"40\", 0.0),\n    (26.0, \"apron\", \"40\", CONTAINER_HEIGHT),\n    (47.0, \"apron\", \"40\", 0.0),\n    (65.0, \"apron\", \"40\", 0.0),\n    (85.0, \"apron\", \"40\", 0.0),\n    (106.0, \"apron\", \"40\", 0.0),\n    (106.0, \"apron\", \"20\", CONTAINER_HEIGHT),\n    (127.0, \"apron\", \"40\", 0.0),\n    (147.0, \"apron\", \"40\", 0.0),\n    (17.0, \"apron_back\", \"40\", 0.0),\n    (37.0, \"apron_back\", \"40\", 0.0),\n    (57.0, \"apron_back\", \"40\", 0.0),\n    (57.0, \"apron_back\", \"40\", CONTAINER_HEIGHT),\n    (78.0, \"apron_back\", \"40\", 0.0),\n    (99.0, \"apron_back\", \"40\", 0.0),\n    (120.0, \"apron_back\", \"40\", 0.0),\n    (141.0, \"apron_back\", \"40\", 0.0),\n)\n\n# How far a box's centre may sit off its row line, in metres. Both yard-side\n# rows are true to within 5 cm: they are set against a kerb. The apron block is\n# the one that is read almost edge-on, and a dead straight line of boxes 10.5 m\n# off the near kerb was the last thing in the shot that still looked generated\n# rather than parked, so those two rows are allowed to wander either way.\n# 1.5 m proved too polite: the two lines held a constant 4.5 m gap, so the eye\n# still read \"two rows\" with a wobble on them. At 2.2 m the near line sets back\n# anywhere from 4.7 m to 8.1 m off the kerb and the far line 9.1 m to 12.7 m,\n# so consecutive boxes step in and out by up to 3.4 m and every bay is at a\n# visibly different distance from the road. The bands still stop just short of\n# each other, so no rear box ever comes forward of a front one.\nROW_DEPTH_JITTER = {\n    \"front\": 0.05,\n    \"back\": 0.05,\n    \"apron\": 2.20,\n    \"apron_back\": 2.20,\n}\n\n# ---------------------------------------------------------------------- lamps\nLAMP_MODEL_HEIGHT = 5.46\nLAMP_TARGET_HEIGHT = 6.40\n# Yard lighting is laid out to light the apron, not to line the kerb. This row\n# has been thinned twice and the lesson from both passes is that pitch is the\n# wrong knob: a 6.4 m mast is still ~34 px tall at 240 m, so the far end of the\n# row never shrinks away -- it just piles up around the vanishing point and the\n# whole line keeps reading as a fence of posts no matter how far apart they\n# stand. At 36 m that pile-up was the complaint, so the row is now *shorter in\n# count* instead: 60 m between masts, 4 of them in shot.\n# The row still has to reach somewhere, though. An earlier version stopped at\n# x = 48 and the masts visibly ran out a third of the way to the horizon, which\n# is the same tell as a road that ends, so the last mast sits at x = 200, past\n# the point where the markings go sub-pixel.\nLAMP_XS = (-40.0, 20.0, 80.0, 140.0, 200.0)\nLAMP_Y = 5.00       # yard side of the kerb, same line the old masts stood on\n# There is deliberately no mast on the apron kerb: the block on that side is\n# read at a grazing angle, so a post in front of it became a foreground stick\n# with nothing to light, and the right-hand ground already has the container\n# block to carry its scale. `build_lamp_posts(arm_toward=+1)` is still able to\n# place one if that side ever needs lighting again.\n# The shot is late afternoon with the sun about 30 degrees up, so the posts are\n# switched off -- which is also what a working yard does. The asset ships with\n# its lens at emission strength 1.0 and the renderer used to hang a 520 W point\n# light under every head, which read as \"who left the lights on at noon\". Set\n# this True (and the caller will light them) for a dusk or night pass.\nLAMPS_LIT = False\n\n# ------------------------------------------------------------------ speed hump\nHUMP_MODEL_HALF_LENGTH = 0.60   # |x| where the model's profile reaches the road\nHUMP_MODEL_PEAK = 0.103\nHUMP_MODEL_HALF_WIDTH = 4.96\nHUMP_MODEL_CENTRE_Y = 3.475\n\n\ndef _import_glb(glb: Path) -> list[bpy.types.Object]:\n    before = set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(glb))\n    return [obj for obj in bpy.data.objects if obj not in before]\n\n\ndef _group(objs: list[bpy.types.Object], name: str) -> bpy.types.Object:\n    \"\"\"Parent the imported roots to a fresh empty without moving anything.\"\"\"\n    root = bpy.data.objects.new(name, None)\n    bpy.context.scene.collection.objects.link(root)\n    members = set(objs)\n    for obj in objs:\n        if obj.parent in members:\n            continue\n        world = obj.matrix_world.copy()\n        obj.parent = root\n        obj.matrix_world = world\n    return root\n\n\ndef _harvest_containers() -> tuple[list[bpy.types.Object], list[bpy.types.Object]]:\n    \"\"\"Import the pack and keep its intact boxes, in world space, split by length.\n\n    63 meshes, but only 37 of them are whole containers -- the rest are cut\n    boxes the pack uses to fill its own scene edges (0.5 x 1.1 x 2.8 m slices).\n    Placing those as if they were containers is what left 1 m gaps in the old\n    row. Returns ``(40 ft, 20 ft)`` so the layout table can pick a length per\n    slot instead of accepting whatever came first.\n    \"\"\"\n    objs = _import_glb(CONTAINER_PACK)\n    meshes = [obj for obj in objs if obj.type == \"MESH\"]\n    empties = [obj for obj in objs if obj.type != \"MESH\"]\n    forties: list[bpy.types.Object] = []\n    twenties: list[bpy.types.Object] = []\n    for obj in meshes:\n        lo, hi = _bbox_world(obj)\n        long_side = max(hi[0] - lo[0], hi[1] - lo[1])\n        if (hi[2] - lo[2]) < 2.0:\n            continue\n        if long_side > 10.0:\n            forties.append(obj)\n        elif long_side > 5.0:\n            twenties.append(obj)\n    keep = set(forties) | set(twenties)\n    for obj in meshes:\n        if obj not in keep:\n            bpy.data.objects.remove(obj, do_unlink=True)\n    for obj in empties:\n        bpy.data.objects.remove(obj, do_unlink=True)\n    for obj in keep:\n        world = obj.matrix_world.copy()\n        obj.parent = None\n        obj.matrix_world = world\n    return forties, twenties\n\n\ndef _bbox_world(obj: bpy.types.Object) -> tuple[list[float], list[float]]:\n    pts = [obj.matrix_world @ v.co for v in obj.data.vertices]\n    return (\n        [min(p[i] for p in pts) for i in range(3)],\n        [max(p[i] for p in pts) for i in range(3)],\n    )\n\n\ndef _yaw_about_centre(obj: bpy.types.Object, angle: float) -> None:\n    \"\"\"Turn ``obj`` about the vertical axis through its own bounding-box centre.\"\"\"\n    lo, hi = _bbox_world(obj)\n    centre = Vector(((lo[0] + hi[0]) * 0.5, (lo[1] + hi[1]) * 0.5, (lo[2] + hi[2]) * 0.5))\n    obj.matrix_world = (\n        Matrix.Translation(centre)\n        @ Matrix.Rotation(angle, 4, \"Z\")\n        @ Matrix.Translation(-centre)\n        @ obj.matrix_world\n    )\n\n\ndef _long_axis_is_x(obj: bpy.types.Object) -> bool:\n    lo, hi = _bbox_world(obj)\n    return (hi[0] - lo[0]) >= (hi[1] - lo[1])\n\n\ndef _place(obj: bpy.types.Object, x: float, y: float, z_base: float) -> tuple[float, float, float]:\n    \"\"\"Sit ``obj`` on ``z_base`` with its bbox centre over ``(x, y)``, long side to the road.\n\n    The layout table is written in road coordinates -- x along the haul road, y\n    away from it -- so a box whose long axis is authored along Y is turned a\n    quarter first. Returns the box's (length, depth, height) after the turn.\n    \"\"\"\n    if not _long_axis_is_x(obj):\n        _yaw_about_centre(obj, math.pi / 2.0)\n    lo, hi = _bbox_world(obj)\n    dims = (hi[0] - lo[0], hi[1] - lo[1], hi[2] - lo[2])\n    obj.matrix_world = (\n        Matrix.Translation(\n            (x - (lo[0] + hi[0]) * 0.5, y - (lo[1] + hi[1]) * 0.5, z_base - lo[2])\n        )\n        @ obj.matrix_world\n    )\n    return dims\n\n\ndef build_cargo_cartons(count: int = 2) -> list[bpy.types.Object]:\n    \"\"\"Import the parcel glb once and clone it for every cargo body.\n\n    The collider is a box of ``CARGO_HALF_EXTENTS``, so the picture only stays\n    honest if the mesh really is that box: the import is scaled by the single\n    factor ``CARGO_SCALE``, its bounding-box centre is moved to the origin, and\n    the transform is baked into the mesh. After that one object is a parcel\n    whose ``location`` is its centre -- the same quantity the simulation reports\n    -- and the clones are ``Object.copy()``, so all bodies share one mesh.\n    \"\"\"\n    asset = MODELS / cfg.CARGO_ASSET\n    imported = _import_glb(asset)\n    meshes = [obj for obj in imported if obj.type == \"MESH\"]\n    if not meshes:\n        raise RuntimeError(f\"{asset.name} imported no mesh\")\n    for obj in imported:\n        if obj.type != \"MESH\":\n            bpy.data.objects.remove(obj, do_unlink=True)\n\n    bpy.ops.object.select_all(action=\"DESELECT\")\n    for obj in meshes:\n        obj.select_set(True)\n    bpy.context.view_layer.objects.active = meshes[0]\n    if len(meshes) > 1:\n        bpy.ops.object.join()\n    proto = meshes[0]\n\n    lo, hi = _bbox_world(proto)\n    centre = Vector(((lo[i] + hi[i]) * 0.5 for i in range(3)))\n    proto.matrix_world = (\n        Matrix.Scale(cfg.CARGO_SCALE, 4) @ Matrix.Translation(-centre) @ proto.matrix_world\n    )\n    bpy.ops.object.select_all(action=\"DESELECT\")\n    proto.select_set(True)\n    bpy.context.view_layer.objects.active = proto\n    bpy.ops.object.transform_apply(location=True, rotation=True, scale=True)\n\n    # Cardboard, not the pack's default: the glb ships a mid-grey that reads as\n    # moulded plastic next to the truck's paint.\n    for slot in proto.material_slots:\n        if slot.material and slot.material.use_nodes:\n            for node in slot.material.node_tree.nodes:\n                if node.type == \"BSDF_PRINCIPLED\":\n                    node.inputs[\"Roughness\"].default_value = 0.82\n                    set_shader_input(node, 'Specular IOR Level', 0.28)\n\n    cartons = [proto]\n    for index in range(1, count):\n        clone = proto.copy()\n        bpy.context.scene.collection.objects.link(clone)\n        cartons.append(clone)\n    for index, obj in enumerate(cartons):\n        obj.name = f\"cargo_{index + 1}\"\n    return cartons\n\n\ndef _bay_hash(row: str, x: float) -> float:\n    \"\"\"Deterministic value in ``[-1, 1]`` for one bay of one row.\n\n    Keyed on ``(row, x)`` rather than on the loop index so a stacked box keeps\n    the placement and the yaw of the box it stands on: an index-keyed value\n    would slide the upper container up to three metres off the lower one.\n    \"\"\"\n    seed = int(round(float(x) * 10.0)) * 7919 + sum(ord(c) for c in row) * 104729\n    return ((seed * 2654435761) % 2003) / 1001.0 - 1.0\n\n\ndef build_container_yard() -> bpy.types.Object:\n    \"\"\"Lay the pack's intact boxes out as two rows behind the fence.\n\n    ``Object.copy()`` shares the mesh datablock, so a box reused twice costs one\n    transform and no geometry; the harvested originals are deleted afterwards so\n    the pack's own depot layout cannot leak into the shot.\n    \"\"\"\n    forties, twenties = _harvest_containers()\n    root = bpy.data.objects.new(\"container_yard\", None)\n    bpy.context.scene.collection.objects.link(root)\n\n    sources = {\"40\": forties, \"20\": twenties}\n    used = {\"40\": 0, \"20\": 0}\n    for index, (x, row, length, z_base) in enumerate(CONTAINER_LAYOUT):\n        pool = sources[length]\n        if not pool:\n            continue\n        source = pool[used[length] % len(pool)]\n        used[length] += 1\n        obj = source.copy()\n        obj.name = f\"container_{row}_{index:02d}\"\n        bpy.context.scene.collection.objects.link(obj)\n\n        # Deterministic jitter: a perfect grid is the loudest generated tell\n        # left, and no RNG keeps the render reproducible. Depth is the one that\n        # matters here -- how far the box sits from its kerb -- see\n        # ``ROW_DEPTH_JITTER``; a degree of yaw is what a box set down by a\n        # crane actually has, and the gaps in the table do the rest.\n        wobble = _bay_hash(row, x)\n        y = CONTAINER_ROWS[row] + wobble * ROW_DEPTH_JITTER[row]\n        _yaw_about_centre(obj, math.radians(wobble * 1.1))\n        _place(obj, x, y, z_base)\n        obj.parent = root\n\n    for obj in forties + twenties:\n        bpy.data.objects.remove(obj, do_unlink=True)\n    return root\n\n\ndef _unlit_lens(objs: list[bpy.types.Object]) -> None:\n    \"\"\"Drop the glb's emissive lamp lens so an unlit post really is unlit.\n\n    The asset authors the lens as white emission at strength 1.0, which in\n    daylight is a glowing panel on every post. Zeroing the strength keeps the\n    lens geometry and its base colour -- it reads as a plastic cover.\n    \"\"\"\n    for obj in objs:\n        if obj.type != \"MESH\":\n            continue\n        for slot in obj.material_slots:\n            mat = slot.material\n            if not mat or not mat.use_nodes:\n                continue\n            bsdf = next(\n                (n for n in mat.node_tree.nodes if n.type == \"BSDF_PRINCIPLED\"), None\n            )\n            if bsdf is None:\n                continue\n            strength = bsdf.inputs.get(\"Emission Strength\")\n            if strength is not None and not strength.is_linked:\n                strength.default_value = 0.0\n\n\ndef build_lamp_posts(\n    xs=LAMP_XS,\n    y: float = LAMP_Y,\n    height: float = LAMP_TARGET_HEIGHT,\n    arm_toward: float = -1.0,\n) -> list[tuple[float, float, float]]:\n    \"\"\"Place the downloaded post along a kerb line.\n\n    The asset's arm reaches +X, so the post is yawed a quarter turn to point it\n    across the road instead of down it. ``arm_toward`` is the *sign of Y* the\n    arm should reach: -1 on the yard kerb, where the road lies at y < 5, and +1\n    on the apron kerb on the camera side, where the road lies at y > -7.6.\n    Yawing both rows the same way is what leaves the apron posts lighting the\n    back of their own block, so the sign is carried through to the head offset\n    the caller hangs its point light on.\n    \"\"\"\n    factor = float(height) / LAMP_MODEL_HEIGHT\n    sign = 1.0 if arm_toward >= 0.0 else -1.0\n    heads: list[tuple[float, float, float]] = []\n    for index, x in enumerate(xs):\n        objs = _import_glb(LAMPPOST)\n        if not LAMPS_LIT:\n            _unlit_lens(objs)\n        root = _group(objs, f\"lamp_post_{index}\")\n        root.location = (float(x), float(y), 0.0)\n        root.rotation_euler = (0.0, 0.0, sign * math.pi / 2.0)\n        root.scale = (factor, factor, factor)\n        heads.append((float(x), float(y) + sign * 1.15 * factor, 5.05 * factor))\n    return heads\n\n\ndef build_speed_hump(\n    height: float, width: float, road_half_width: float\n) -> bpy.types.Object:\n    \"\"\"Skin the collider bump with the downloaded hump.\n\n    Three separate factors, each chosen against the collider rather than the\n    asset:\n\n    * X maps the model's ramp feet (|x| = 0.60) onto the collider's half width,\n      so the hump starts rising exactly where the collision profile does;\n    * Z puts the model's 0.103 m plateau on the requested peak height;\n    * Y spans the visible road width.\n\n    The model's top is flatter than a sine, so mid-slope it sits up to ~26 mm\n    above the collision profile -- the tyre sinks into the hump by that much\n    instead of floating over it, which is the error that reads correctly.\n    \"\"\"\n    objs = _import_glb(SPEED_HUMP)\n    root = _group(objs, \"speed_hump\")\n    root.scale = (\n        (float(width) * 0.5) / HUMP_MODEL_HALF_LENGTH,\n        (2.0 * float(road_half_width)) / (2.0 * HUMP_MODEL_HALF_WIDTH),\n        float(height) / HUMP_MODEL_PEAK,\n    )\n    root.location = (\n        cfg.SPEED_BUMP_CENTER_X,\n        -HUMP_MODEL_CENTRE_Y * root.scale[1],\n        0.0,\n    )\n    return root\n", "scene_support.flatbed_speed_bump.import_truck": "\"\"\"Adapt the desktop CC-BY truck to the benchmark's chassis/deck rig.\n\nThe glb is a real-proportioned three-axle flatbed authored at 26.03 x 8.87 x\n8.86 model units. It is *not* a 1:1 asset -- it is a real truck blown up to\nroughly 3.4x life size, so every proportion is right and the absolute size is\nnot. This adapter therefore applies exactly one factor to it, ``scale``, on all\nthree axes::\n\n    X = cfg.model_x(p.y)      Y = p.x * scale      Z = cfg.model_z(p.z)\n\n``cfg.TRUCK_SCALE`` is that factor and ``cfg.model_x`` / ``cfg.model_z`` are the\nsame two functions the collision rig is built from, so the visible mesh and the\ncollider cannot disagree -- if the deck plank moves, the box the cargo rests on\nmoves with it. Nothing is stretched along a single axis: an earlier version\ncorbelled the 0.70 m between the model's sill and its bed into one band so the\ndeck could stay at 1.25 m, which is exactly what made the cab read as mounted on\nstilts. The rig follows the model instead, so the deck sits at 0.737 m.\n\nThe one part that is not simply ``scale`` is the tyre: the rig models a single\nwheel radius (``cfg.WHEEL_RADIUS``), which is the front tyre's 1.635 units times\n``scale``. The front tyres therefore land exactly, and the narrower rear tandem\n(1.489 units) is scaled up by 9.8 % so all six tyres can stand on the road. The\nfront axle is the one that strikes the bump, so the contact that matters is\nexact.\n\nMaterials: the glb's paint map is a near-white panel sheet with rust along the\nseams (see ``assets/models/flatbed_unity3d.glb`` image 0), and its paint\nmaterial is glTF ``roughness 0.0`` -- a mirror. The dark olive on the published\npage is that mirror reflecting a dark environment, not a colour in the texture.\nThe tint below reproduces it by multiplying the map, so the grime survives, and\n``PAINT_ROUGHNESS`` makes it read as paint rather than chrome.\n\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nfrom pathlib import Path\n\nimport bpy\nfrom mathutils import Vector\n\nimport scene_support.flatbed_speed_bump.scene_config as cfg\n\nASSET = _PCVE_ROOT / 'assets' / 'models' / 'flatbed_unity3d.glb'\n\n# Multiplied into the paint map: a near-white base with baked rust streaks\n# becomes the dark olive the published model shows, streaks and panel dirt\n# intact.\nPAINT_TINT = (0.30, 0.32, 0.20)\nPAINT_ROUGHNESS = 0.34\nWHEEL_ROUGHNESS = 0.52\n\n\ndef _bbox(points):\n    lo = Vector(tuple(min(p[i] for p in points) for i in range(3)))\n    hi = Vector(tuple(max(p[i] for p in points) for i in range(3)))\n    return lo, hi, (lo + hi) * 0.5\n\n\ndef _tint_base_color(mat, tint) -> None:\n    \"\"\"Multiply ``mat``'s base-colour map by ``tint`` (the map is kept).\"\"\"\n    if not mat or not mat.use_nodes:\n        return\n    nodes = mat.node_tree.nodes\n    links = mat.node_tree.links\n    bsdf = next((n for n in nodes if n.type == 'BSDF_PRINCIPLED'), None)\n    if bsdf is None or not bsdf.inputs['Base Color'].is_linked:\n        return\n    source = bsdf.inputs['Base Color'].links[0].from_socket\n    mix = nodes.new('ShaderNodeMix')\n    mix.name = 'paint_tint'\n    mix.data_type = 'RGBA'\n    mix.blend_type = 'MULTIPLY'\n    mix.clamp_factor = True\n    sockets = {s.identifier: s for s in mix.inputs}\n    factor = sockets.get('Factor_Float') or mix.inputs[0]\n    factor.default_value = 1.0\n    color_a = sockets.get('A_Color') or mix.inputs[6]\n    color_b = sockets.get('B_Color') or mix.inputs[7]\n    color_b.default_value = (tint[0], tint[1], tint[2], 1.0)\n    result = next((s for s in mix.outputs if s.identifier == 'Result_Color'), mix.outputs[2])\n    links.new(source, color_a)\n    links.new(result, bsdf.inputs['Base Color'])\n\n\ndef build_truck(asset=None):\n    source = Path(asset) if asset else ASSET\n    if not source.is_file():\n        raise FileNotFoundError(f\"Required truck model not found: {source}\")\n    bpy.ops.import_scene.gltf(filepath=str(source))\n    imported = list(bpy.context.selected_objects)\n    bpy.context.view_layer.update()\n    meshes = [o for o in imported if o.type == 'MESH']\n    baked = [(o, [o.matrix_world @ v.co for v in o.data.vertices]) for o in meshes]\n    for o in meshes:\n        o.parent = None\n        o.matrix_world.identity()\n    for o in imported:\n        if o.type != 'MESH':\n            bpy.data.objects.remove(o, do_unlink=True)\n\n    # --- wheel inventory: axle positions drive every later anchor ----------\n    wheel_info = {}\n    for obj, points in baked:\n        if 'Wheel' in obj.name and points:\n            lo, hi, centre = _bbox(points)\n            wheel_info[obj.name] = (lo, hi, centre)\n    front = [c.y for n, (_lo, _hi, c) in wheel_info.items() if 'F_Wheel' in n]\n    rear = [c.y for n, (_lo, _hi, c) in wheel_info.items() if 'F_Wheel' not in n]\n    if not front or not rear:\n        raise RuntimeError('flatbed glb: expected front and rear wheels by name')\n\n    scale = cfg.TRUCK_SCALE\n    # The rig's axle spacing is ``scale`` times the model's by construction;\n    # check it here so a swapped asset fails loudly instead of importing with a\n    # silently wrong wheelbase.\n    model_spread = abs(sum(front) / len(front) - sum(rear) / len(rear))\n    if abs(model_spread * scale - cfg.WHEEL_BASE) > 1e-3:\n        raise RuntimeError(\n            f'flatbed glb: axle spread {model_spread:.4f} x {scale:.6f} = '\n            f'{model_spread * scale:.4f} m, rig has {cfg.WHEEL_BASE:.4f} m'\n        )\n\n    def to_vehicle(p: Vector) -> Vector:\n        \"\"\"Model units -> vehicle frame (road at -R, axle line at 0, nose +X).\"\"\"\n        return Vector((\n            cfg.model_x(p.y),\n            p.x * scale,\n            cfg.model_z(p.z),\n        ))\n\n    chassis = bpy.data.objects.new('truck_chassis', None)\n    deck = bpy.data.objects.new('truck_deck', None)\n    bpy.context.collection.objects.link(chassis)\n    bpy.context.collection.objects.link(deck)\n\n    wheels = []\n    for obj, points in baked:\n        if obj.name in wheel_info:\n            lo, hi, centre = wheel_info[obj.name]\n            # The rig has one wheel radius; the front tyre is the exact one, the\n            # rear tandem is 9.8 % larger (see the module docstring).\n            wheel_scale = cfg.WHEEL_RADIUS / ((hi.z - lo.z) * 0.5)\n            radius = (hi.z - lo.z) * 0.5 * wheel_scale\n            position = to_vehicle(centre)\n            pivot = bpy.data.objects.new(obj.name + '_axle', None)\n            bpy.context.collection.objects.link(pivot)\n            pivot.parent = chassis\n            # The tyre has to meet the road: its centre goes on the physics axle\n            # line, not where the body warp would have put it.\n            pivot.location = (position.x, position.y, -cfg.CHASSIS_COM_Z)\n            pivot['rolling_radius'] = radius\n            obj.parent = pivot\n            for v, p in zip(obj.data.vertices, points):\n                q = p - centre\n                # The model's axle runs along X; the pivot spins about its own Y.\n                v.co = (-q.y * wheel_scale, q.x * wheel_scale, q.z * wheel_scale)\n            wheels.append(pivot)\n        else:\n            obj.parent = chassis\n            for v, p in zip(obj.data.vertices, points):\n                vehicle = to_vehicle(p)\n                v.co = (vehicle.x, vehicle.y, vehicle.z - cfg.CHASSIS_COM_Z)\n            # Split the bed from the cab so the original suspension still works.\n            # Faces behind the cab and above the sill belong to the bed.\n            bed_faces = [poly.index for poly in obj.data.polygons if all(\n                points[i].y > cfg.MODEL_BED_FRONT_Y and points[i].z > cfg.MODEL_BED_SILL_Z\n                for i in poly.vertices)]\n            if bed_faces:\n                bpy.ops.object.select_all(action='DESELECT')\n                obj.select_set(True)\n                bpy.context.view_layer.objects.active = obj\n                bpy.ops.object.mode_set(mode='EDIT')\n                bpy.ops.mesh.select_all(action='DESELECT')\n                bpy.ops.object.mode_set(mode='OBJECT')\n                for index in bed_faces:\n                    obj.data.polygons[index].select = True\n                bpy.ops.object.mode_set(mode='EDIT')\n                bpy.ops.mesh.separate(type='SELECTED')\n                bpy.ops.object.mode_set(mode='OBJECT')\n                for part in list(bpy.context.selected_objects):\n                    if part != obj:\n                        part.name = 'imported_sprung_' + part.name\n                        part.parent = deck\n                        for v in part.data.vertices:\n                            v.co -= Vector((\n                                cfg.DECK_CENTER_X, 0,\n                                cfg.DECK_Z - cfg.CHASSIS_COM_Z,\n                            ))\n        for mat in obj.data.materials:\n            if mat and mat.use_nodes:\n                bsdf = next((n for n in mat.node_tree.nodes\n                             if n.type == 'BSDF_PRINCIPLED'), None)\n                if bsdf is None:\n                    continue\n                if 'Paint' in mat.name:\n                    bsdf.inputs['Roughness'].default_value = PAINT_ROUGHNESS\n                    _tint_base_color(mat, PAINT_TINT)\n                elif 'Wheel' in mat.name:\n                    bsdf.inputs['Roughness'].default_value = WHEEL_ROUGHNESS\n                else:\n                    bsdf.inputs['Roughness'].default_value = 0.40\n    return chassis, deck, wheels\n", "scene_support.flatbed_speed_bump.runtime_support": "\"\"\"Local runtime discovery; scripts also work in ordinary Python/Blender installs.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport os\nimport sys\nfrom pathlib import Path\n\nROOT = _PCVE_ROOT\n_dll_handles = []\nif os.name == \"nt\":\n    directory = Path(sys.prefix) / \"Library/bin\"\n    if directory.exists():\n        _dll_handles.append(os.add_dll_directory(str(directory)))\n\n\ndef python_for(role):\n    sys.path.insert(0, str(ROOT/'clean_scripts'))\n    from pcve_scene_runtime import python_for as resolve_python\n    return resolve_python(role)\n", "scene_support.flatbed_speed_bump.scene_config": "\"\"\"Shared geometry and baseline parameters for the flatbed-speed-bump scene.\n\nBoth the PyBullet simulation and the Blender renderer import these constants so\nthe collision shapes and the visible meshes cannot drift apart, and so the\nscene's three exposed controls have exactly one definition.\n\nWorld conventions\n-----------------\n* The truck is driven along world **+X**; the cab faces +X.\n* **+Y** is the far kerb (the freight-yard side); **-Y** is the near kerb\n  (safety fence, cones) that faces the camera.\n* Everything about the truck is expressed in the **vehicle reference frame\n  V**: the origin sits on the wheel-axle line at mid-wheelbase, i.e.\n  ``WHEEL_RADIUS`` above the road, so ``V z = 0`` is the axle height and the\n  road surface is at ``V z = -WHEEL_RADIUS``. Chassis-local coordinates are\n  V-relative values shifted by ``-CHASSIS_COM_Z``, because a multibody's base\n  position *is* its centre of mass.\n\nWhy the bed is its own body\n---------------------------\nA rigid truck that clears a speed bump flies as one piece, and so does\nanything resting on it: while the vehicle is ballistic the bed and its cargo\nshare exactly the same acceleration, so the cargo can never leave the bed no\nmatter how violent the jump looks. Making the deck a *sprung* body on a\nprismatic suspension is what actually throws the cargo: the deck overshoots the\nchassis and can be pulled down at well over 1 g on the rebound, which is the\none condition under which a loose carton separates from it.\n\"\"\"\n\nfrom __future__ import annotations\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\n# --------------------------------------------------------------------- truck\n#\n# The rig is *derived from* the asset, not fitted to it. ``flatbed_unity3d.glb``\n# is a real-proportioned three-axle flatbed authored at 26.03 x 8.87 x 8.86\n# model units, and it is placed by ONE factor, ``TRUCK_SCALE``, applied to every\n# vertex on all three axes -- ``model_x`` / ``model_z`` below plus\n# ``p.x * TRUCK_SCALE`` are the whole mapping, and ``import_truck`` calls the\n# same two functions. There is no per-axis correction left anywhere, so every\n# proportion the artist built survives.\n#\n# That is why the deck sits at 0.737 m and the wheelbase is 3.068 m instead of\n# at round numbers: those are where this truck's bed and axles actually are. Any\n# rig that wants the deck higher has to stretch the 0.70 m between the sill and\n# the bed, and that stretch is exactly what reads as \"the cab is on stilts\".\n#\n# The factor itself is the front tyre radius over the rig's, which keeps the\n# 0.34 m wheel: the 0.17 m bump therefore stays at half a wheel radius and the\n# suspension keeps being excited in the band it was tuned for.\n\n# Measured on the asset, in model units (_dump_truck_dimensions.py prints them).\nMODEL_GROUND_Z = -4.43          # tyre contact plane\nMODEL_WHEEL_R = 1.635           # front tyre radius\nMODEL_FRONT_AXLE_Y = -11.2425\nMODEL_REAR_AXLE_Y = 3.5119      # mean of the rear tandem\nMODEL_BED_TOP_Z = -0.887        # up-facing deck plank, level with the tyre tops\nMODEL_BED_FRONT_Y = -6.46       # nose end of the deck, where the cab ends\nMODEL_BED_SILL_Z = -1.23        # lowest bed face; below this it is still frame\nMODEL_BED_Y = (-6.45, 9.64)\nMODEL_BED_X = (-4.11, 4.09)\nMODEL_CAB_Y = (-16.39, -6.51)\nMODEL_CAB_X = (-4.46, 4.41)\nMODEL_CAB_Z = (-1.23, 4.43)\nMODEL_FRAME_Y = (-15.75, 9.57)\nMODEL_FRAME_X = (-4.15, 4.13)\n\nTRUCK_SCALE = 0.34 / MODEL_WHEEL_R                    # 0.2079511\n\nWHEEL_RADIUS = MODEL_WHEEL_R * TRUCK_SCALE            # 0.3400\nWHEEL_WIDTH = 1.437 * TRUCK_SCALE                     # 0.2988, front tyre\nWHEEL_BASE = (MODEL_REAR_AXLE_Y - MODEL_FRONT_AXLE_Y) * TRUCK_SCALE\nWHEEL_XS = (-0.5 * WHEEL_BASE, 0.5 * WHEEL_BASE)      # 3.0682 m axle spacing\n# The front axle strikes the bump first, so its track is what the four collision\n# cylinders use; the rear tandem is narrower (0.591 m half-track) and only its\n# visible wheels sit there.\nWHEEL_YS = (-3.398 * TRUCK_SCALE, 3.398 * TRUCK_SCALE)  # 1.4132 m track\n\n\ndef model_x(y: float) -> float:\n    \"\"\"Model +Y (rearwards) -> vehicle X, front axle on ``+WHEEL_BASE / 2``.\"\"\"\n    return 0.5 * WHEEL_BASE - (y - MODEL_FRONT_AXLE_Y) * TRUCK_SCALE\n\n\ndef model_z(z: float) -> float:\n    \"\"\"Model +Z -> vehicle Z, with the tyre contact patch landing on ``-R``.\"\"\"\n    return -WHEEL_RADIUS + (z - MODEL_GROUND_Z) * TRUCK_SCALE\n\n\n# The chassis body's origin is its centre of mass, placed this high above the\n# ground contact line; the collision shapes below are offset from it. 0.55 m is\n# the height the pitch and roll response was tuned at, and the tyre radius is\n# unchanged, so it stays.\nCHASSIS_MASS = 900.0\nCHASSIS_COM_Z = 0.55\n# Underbody rail, cut off at the axle line. The model's sill reaches down to\n# 0.108 m above the road, which is below the 0.17 m bump crest -- a collider\n# that deep would ride up on the bump, so the box stops at V z = 0. The sim\n# centres this box on X = 0 while the model's own rail is 0.16 m off-centre, so\n# it takes the shorter side: that keeps it inside the body at both ends.\nFRAME_HALF = (\n    min(abs(model_x(MODEL_FRAME_Y[0])), abs(model_x(MODEL_FRAME_Y[1]))),\n    0.5 * (MODEL_FRAME_X[1] - MODEL_FRAME_X[0]) * TRUCK_SCALE,\n    0.125,\n)\nFRAME_Z = 0.125\n# The cab's collision box starts behind the deck's front edge only if it is\n# pushed far enough forward: an overlapping box would press on the deck and\n# lock the suspension solid at zero travel. Here the model's own gap (12 mm) is\n# what separates them; the joint is prismatic in Z, so the deck cannot rotate\n# into the cab.\nCAB_HALF = (\n    abs(0.5 * (model_x(MODEL_CAB_Y[1]) - model_x(MODEL_CAB_Y[0]))),\n    0.5 * (MODEL_CAB_X[1] - MODEL_CAB_X[0]) * TRUCK_SCALE,\n    0.5 * (model_z(MODEL_CAB_Z[1]) - model_z(MODEL_CAB_Z[0])),\n)\nCAB_X = 0.5 * (model_x(MODEL_CAB_Y[1]) + model_x(MODEL_CAB_Y[0]))\nCAB_Z = 0.5 * (model_z(MODEL_CAB_Z[1]) + model_z(MODEL_CAB_Z[0]))\n\n# ------------------------------------------------------- sprung flatbed deck\n\nBED_MASS = 350.0\nDECK_HALF = (\n    abs(0.5 * (model_x(MODEL_BED_Y[1]) - model_x(MODEL_BED_Y[0]))),\n    0.5 * (MODEL_BED_X[1] - MODEL_BED_X[0]) * TRUCK_SCALE,\n    # A 50 mm plate: thin enough to hide inside the model's bed slab, which is\n    # 0.071 m thick at this scale, so the 0.05 m of collision below the plank\n    # surface never pokes out under the visible sill.\n    0.025,\n)\nDECK_CENTER_X = 0.5 * (model_x(MODEL_BED_Y[1]) + model_x(MODEL_BED_Y[0]))\nDECK_TOP_Z = model_z(MODEL_BED_TOP_Z)     # V-frame deck surface, 0.3968\nDECK_Z = DECK_TOP_Z - DECK_HALF[2]        # V-frame centre of the deck at rest\nDECK_FRONT_X = DECK_CENTER_X + DECK_HALF[0]\nDECK_REAR_X = DECK_CENTER_X - DECK_HALF[0]\n\n# Prismatic travel of the deck on the chassis: down is compression, up is droop.\n# Down is capped by the 0.097 m between the deck plate and the frame top.\nSUSPENSION_TRAVEL_DOWN = 0.09\nSUSPENSION_TRAVEL_UP = 0.07\n# 40 kN/m on the 350 kg deck is 1.70 Hz. That is far softer than the 280 kN/m\n# the 2.28 m rig used, and it has to be: what a chassis feeds the deck is the\n# gap between the two axles clearing the bump, and this wheelbase is 3.068 m\n# rather than 2.28 m, i.e. 2.9 Hz instead of 3.9 Hz. A deck stiff enough to\n# follow the chassis over the bump just rides with it, and then the cargo shares\n# its acceleration and never leaves the planks. `_sweep_suspension.py` over\n# 40-280 kN/m x damping ratio 0.12/0.25/0.35 put the launch peak here: 65 mm of\n# deck clearance and 7 airborne frames, against 40 mm and 3 at 280 kN/m.\nSUSPENSION_STIFFNESS = 40_000.0\nSUSPENSION_DAMPING = 1_870.0\n# Bump and droop stops: a stiffer one-sided spring takes over past the travel\n# limits, which is what keeps the deck from driving into the frame.\nSTOP_STIFFNESS = 700_000.0\nSTOP_DAMPING = 6_000.0\n# Hard cap on what the suspension may transmit, as a multiple of the deck's\n# weight. This is what keeps the explicit integration stable when the chassis\n# lands hard: uncapped, a 0.16 m bump sent the deck's travel into the tens of\n# metres.\nSUSPENSION_FORCE_LIMIT_UP = 14.0\nSUSPENSION_FORCE_LIMIT_DOWN = 4.0\n\nCHASSIS_ANGULAR_DAMPING = 0.12\n# The wheels are cylinders fixed to the chassis; they have no axle of their own\n# and cannot spin, so any real Coulomb coefficient turns them into skids that\n# stop the truck (about 0.96 g) long before it reaches the bump. Giving them a\n# near-frictionless contact is what a free-rolling tyre actually looks like\n# here: it still carries the full normal load, so the bump still kicks the\n# truck, it just does not drag.\nWHEEL_ROAD_FRICTION = 0.02\n# Cruise control, as a real force applied at the chassis centre of mass rather\n# than a velocity override. The override was the one thing that made this scene\n# unphysical: resetting the linear velocity every substep threw away the contact\n# impulse's linear part while keeping its angular part, which pumped angular\n# momentum into the chassis and stood the truck on its tail -- an 87 degree\n# wheelie on bumps as small as 0.10 m. A force at the centre of mass cannot\n# torque the chassis, so the pitch it produces is only what the bump really\n# produces.\nDRIVE_FORCE_GAIN = 200_000.0       # N per m/s of speed error\nDRIVE_FORCE_MAX = 25_000.0         # N, about 18 m/s^2 on the laden truck\n\n# ------------------------------------------------------------------- cargo\n# Two identical parcels ride loose on the bed, abreast and almost touching:\n# side by side across the deck, parallel to its long axis, 8 mm apart. The gap\n# is not decorative -- spawning them truly coincident makes Bullet fire a\n# separation impulse on frame 1 -- but it is small enough that the pair reads as\n# one tidy load instead of two boxes parked at random.\n#\n# The parcel is the ``carton_box_05_closed`` glb, measured at 31.5488 x 39.9721\n# x 25.8244 model units with its base on z = 0 (see ``_dump_asset_bounds.py``).\n# One factor takes that to a real parcel: CARGO_SCALE puts the 25.82 height at\n# 0.52 m -- the height the old procedural crate had, so the suspension tuning\n# and the 0.20 friction band still describe the same load. x and y are *not*\n# chosen, they follow the model's own 1.222 : 1.548 : 1 aspect, which is why\n# the footprint comes out 0.635 x 0.805 instead of the old 0.64 x 0.56.\n\nCARGO_ASSET = \"carton_box_05_closed.glb\"\nCARGO_MODEL_SIZE = (31.5488, 39.9721, 25.8244)\nCARGO_TARGET_HEIGHT = 0.52\nCARGO_SCALE = CARGO_TARGET_HEIGHT / CARGO_MODEL_SIZE[2]          # 0.0201362\nCARGO_SIZE = tuple(size * CARGO_SCALE for size in CARGO_MODEL_SIZE)\n\nCARGO_HALF_EXTENTS = (\n    tuple(0.5 * size for size in CARGO_SIZE),                    # 0.3176 x 0.4024 x 0.26\n    tuple(0.5 * size for size in CARGO_SIZE),\n)\n# The pair is abreast in Y but staggered in X by 0.90 m, and the near-side\n# parcel (index 0, -Y, the camera side) is the one set back: its rear face is\n# 0.65 m from the tail edge of the planks, and its centre of mass is 0.97 m\n# from it. That is the whole point of the scene now. The deck lags the chassis\n# on the rebound and the loose parcel lags the deck, so in deck coordinates it\n# travels aft during the strike; mid-deck that aft travel is all spent sliding\n# on the planks, and moving the pair to the tail converts the same aft travel\n# into a parcel going over the back edge while the far parcel rides it out as\n# the control.\n#\n# Both numbers are measured, not chosen, and `_probe_cargo_xs.py` is the\n# measurement: it walks one parcel at a time and reports whether it is still\n# aboard at t = 4 s. The aft slip is 1.0-1.5 m in deck coordinates, so a parcel\n# has to start within ~1.0 m of the tail edge to go over, and the other has to\n# start at least ~1.85 m from it to survive -- which is why the two cannot sit\n# at the same x and why the stagger is 0.9 m rather than the \"just slightly\n# back\" a still frame would suggest. At this split the near parcel leaves at\n# the 9 m/s baseline and still leaves at 7 m/s; the far one does not leave at\n# either, which is what makes the shot readable: one parcel on the road, one\n# still on the planks.\nCARGO_DECK_LOCAL_XS = (-0.70, 0.20)    # deck-local x; -X is aft, 0 = deck centre\nCARGO_GAP_Y = 0.008                     # mm-scale only: see the note above\nCARGO_LOCAL_XS = tuple(DECK_CENTER_X + x for x in CARGO_DECK_LOCAL_XS)\nCARGO_LOCAL_YS = (\n    -(CARGO_HALF_EXTENTS[0][1] + 0.5 * CARGO_GAP_Y),   # near kerb, set back\n    +(CARGO_HALF_EXTENTS[0][1] + 0.5 * CARGO_GAP_Y),   # far kerb, forward\n)\n\n# --------------------------------------------------------------- speed bump\n# A rounded (sine-profile) bump spanning the full road width. Its width stays\n# below the truck's wheelbase, so the two axles strike it separately and the\n# bed is pitched as well as heaved.\n\nSPEED_BUMP_CENTER_X = 0.0\nSPEED_BUMP_WIDTH = 1.34\nSPEED_BUMP_SEGMENTS = 24\n\n# ------------------------------------------------------------------- roadway\n\nROAD_HALF_LENGTH = 70.0\nROAD_HALF_WIDTH = 4.0\nROAD_SURFACE_Z = 0.0\n\n# Truck spawn: far enough back that the approach, the strike, the flight and\n# the landing all fit inside one short clip.\nTRUCK_START_X = -7.0\n\n# ---------------------------------------------------------------- baseline\n\n# The three controls the benchmark exposes, plus the surfaces that are\n# deliberately fixed so a single-variable edit really is single-variable.\nBASELINE_PHYSICS = {\n    \"truck_speed\": 9.0,          # m/s -- about 32 km/h, deliberately too fast\n    \"speed_bump_height\": 0.17,   # m   -- peak height of the rounded bump\n    # 0.20 sits in the middle of the band that matters: below it the cartons\n    # skid off the deck, above it they grip and stay, so both directions of the\n    # edit read as different outcomes. At 0.34 the high side had already\n    # saturated.\n    \"cargo_friction\": 0.20,      # --  cargo box <-> deck pair friction\n}\nFIXED_PHYSICS = {\n    \"deck_friction\": 0.70,       # the deck's own coefficient; the pair with the\n                                 # cargo is what the exposed knob scales\n    \"road_friction\": 0.96,\n    \"cargo_mass\": 42.0,\n    \"gravity_z\": -9.8,\n}\n\n# The camera is a fixed vantage on the near-kerb side of the road, so the truck\n# drives through the frame instead of the frame driving with it. A chase rig\n# would hold the truck still on screen and read the throw only as background\n# motion, which hides the one thing the scene exists to show. It sits on the -Y\n# (camera-facing) side and is framed *left*: the start of the run (the truck\n# intact at x = -7) must be fully in frame, and only the stretch the truck needs\n# to clear the bump matters -- the empty haul road past the landing is left out\n# of shot, so no dead runway dominates the right half of the frame.\nSTATIC_CAMERA_LOCATION = (0.0, -12.0, 3.3)\nSTATIC_CAMERA_TARGET = (1.0, 0.0, 1.15)\nSTATIC_CAMERA_LENS_MM = 26.0\n\nBASELINE_RENDER = {\n    \"fps\": 24,\n    \"duration_sec\": 4.0,\n    # Matches the other rigid-body suites in this repo. EEVEE Next holds about\n    # 14 s per frame here at 960x540/32, so a full clip is roughly 18 minutes;\n    # 1280x720/48 is about three times that for no visible gain.\n    \"resolution\": (960, 540),\n    \"samples\": 32,\n    # The clip is a bolted-down camera by requirement, so it has to hold a run\n    # of 41 m: see ``render_flatbed_speed_bump.CAMERA_PRESETS``. ``static`` only\n    # works for one still.\n    \"camera_mode\": \"clip4s\",\n}\n\n# ------------------------------------------------------------------ helpers\n\n\ndef bed_rest_top_z() -> float:\n    \"\"\"World z of the deck surface with the truck sitting at rest.\"\"\"\n    return WHEEL_RADIUS + DECK_TOP_Z\n\n\ndef road_length_for(speed: float, duration_sec: float, *, margin: float = 12.0) -> float:\n    \"\"\"Half-length that keeps a truck at ``speed`` on the slab for the clip.\"\"\"\n    reach = abs(float(TRUCK_START_X)) + abs(float(speed)) * float(duration_sec) + margin\n    return max(ROAD_HALF_LENGTH, reach)\n", "scene_support.flatbed_speed_bump": "\"\"\"Shared support modules for flatbed_speed_bump.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n", "cache_contract": "\"\"\"Compatibility contract for flatbed trajectories and renderer replays.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport hashlib,json\nfrom pathlib import Path\ndef _scene_directory():\n    scripts_root = _PCVE_ROOT / 'clean_scripts'\n    for candidate in (scripts_root / \"rigid_rigid\" / \"flatbed_speed_bump\", scripts_root / \"flatbed_speed_bump\"):\n        if candidate.is_dir():\n            return candidate\n    raise FileNotFoundError(\"Scene directory not found for flatbed_speed_bump\")\n\n\nCACHE_SCHEMA_VERSION=4\n\ndef signature(parameters):\n    import hashlib, json\n    scene_dir = _PCVE_SCENE_ROOT\n    common_dir = _PCVE_ROOT / \"clean_scripts\"\n    files = list(scene_dir.glob(\"*.py\")) + list(common_dir.glob(\"*.py\"))\n    implementation = {str(path.relative_to(_PCVE_ROOT)): hashlib.sha256(path.read_bytes()).hexdigest()\n                      for path in files if path.is_file()}\n    payload = dict(implementation=implementation, scenario=parameters)\n    return hashlib.sha256(json.dumps(payload, sort_keys=True, allow_nan=False, default=str).encode()).hexdigest()\ndef validate_cache(data,requested=None):\n    message='Incompatible flatbed physics cache: parameters, geometry or implementation changed; resimulate first.'\n    if data.get('schema_version')!=CACHE_SCHEMA_VERSION or data.get('scene')!='flatbed_speed_bump':raise ValueError(message)\n    params=data.get('simulation_parameters',{})\n    if data.get('simulation_signature')!=signature(params):raise ValueError(message)\n    for name,value in (requested or {}).items():\n        if value is not None and params.get(name)!=value:raise ValueError(message+' Mismatch: '+name)\n    count=max(2,round(params['fps']*params['duration_sec']))\n    if data.get('fps')!=params['fps'] or data.get('duration_sec')!=params['duration_sec'] or data.get('frame_end')!=count or len(data.get('frames',[]))!=count:raise ValueError(message)\n    for name,value in data['physics_parameters'].items():\n        if name in params and value!=params[name]:raise ValueError(message)\n", "import_props": "\"\"\"Import the downloaded props: containers, lamp posts, speed hump, parcels.\n\nNone of these are physics bodies except the parcels, which are the *picture* of\ncargo bodies the simulation owns; the rest never appear in the ground truth.\nThree are placed at their authored size, **unscaled**:\n\n* the containers are real 12.1 / 6.4 x 2.4 x 2.9 m boxes, turned and shifted\n  only, laid out as two rows with their long sides to the road (see\n  ``CONTAINER_LAYOUT``);\n* the lamp posts are a single uniform 1.172x, because 6.40 m is the height the\n  lighting rig was built around and a lamp post is one rigid object.\n\nThe speed hump is the one non-uniform placement in the scene, and it is not a\nprop: it is the *picture* of a collider that already exists as a sine profile in\n``scene_config``. Its three factors map the model's ramp feet onto the\ncollider's half width, its 0.103 m plateau onto the requested peak, and its\n9.92 m span onto the 8 m road. A single factor cannot do all three -- at the\nwidth factor it would be 0.083 m tall, so the truck would visibly ride 87 mm\nabove the hump it is colliding with; at the height factor it would be 16.4 m\nwide, twice the road. Nothing here is animated, so no vertex-level adapter like\n``import_truck`` is needed.\n\nMeasured from the glbs (glTF units are metres):\n\n* ``container_pack`` -- a whole depot, 29.8 x 43.2 x 8.8 m, 63 meshes, 40 ft\n  boxes at 12.06 x 2.42 x 2.92 m stacked up to three high, ground plane at\n  z = 0. Long axis along +X, so the boxes present their long sides to the road.\n* ``lamppost`` -- one 5.46 m post, arm reaching +X to x = 1.25, base at z = 0.\n* ``speed_bump`` -- one hump, 2.0 m along X (the travel direction), 9.92 m\n  along Y, plateau at z = +0.103, moulded skirt down to z = -0.208. It goes\n  flat at |x| ~ 0.60 and peaks across |x| < 0.15.\n* ``carton_box_05_closed`` -- one parcel, 31.5488 x 39.9721 x 25.8244 model\n  units, centred on x = y = 0 with its base on z = 0. Unlike the three above it\n  is scaled, by the single ``CARGO_SCALE`` factor, because it has to match a\n  box collider whose half extents the simulation owns.\n\"\"\"\n\nfrom __future__ import annotations\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\nimport sys\nfrom pathlib import Path\nsys.path.insert(0, str(_PCVE_ROOT / 'clean_scripts'))\nfrom pcve_blender_compat import (shader_socket, set_shader_input, eevee_engine, set_eevee_property, set_color_property)\n\nimport math\nfrom pathlib import Path\n\nimport bpy\nfrom mathutils import Matrix, Vector\n\nimport scene_support.flatbed_speed_bump.scene_config as cfg\n\nMODELS = _PCVE_ROOT / \"assets\" / \"models\"\nCONTAINER_PACK = MODELS / \"container_pack.glb\"\nLAMPPOST = MODELS / \"lamppost.glb\"\nSPEED_HUMP = MODELS / \"speed_bump.glb\"\n\n# --------------------------------------------------------------- container yard\n# A yard is rows, not a wall. The previous layout quarter-turned every box so\n# its 2.4 m end faced the road, then set them at a 2.5 m pitch from x = -22 to\n# +58: 66 boxes shoulder to shoulder, which from the fixed camera read as a\n# corrugated fence -- and because the only face in shot was a narrow end panel,\n# every container looked taller than it is. This layout is the other reading of\n# the same asset: long sides to the road, two rows 4.75 m apart, real gaps and\n# staggered joints. The shot now shows the 12.1 m side the model was built\n# with, ~13 boxes instead of 66, and the place reads as a depot with depth\n# rather than as a barrier.\nCONTAINER_FRONT_Y = 9.20    # road-side row centre; front face lands on y = 8.0\nCONTAINER_BACK_Y = 13.95    # second row, one bay behind, joints staggered\n# The camera stands on the -Y apron, so everything on that side is seen at a\n# grazing angle and swallows the right half of the frame as bare ground. A\n# second block fills it: same asset, same orientation, but read as a yard block\n# rather than a row -- two staggered lines 4.5 m apart, so the near line hides\n# the far one except through its gaps, which is what gives the side its depth.\n# The near line starts at x = 8 because below ~x = 5 the block falls outside the\n# right edge of the frame: from this camera the apron is only visible from about\n# 30 m ahead, and a container 10.5 m off the kerb only enters the frustum at\n# x ~ 5.\nCONTAINER_APRON_Y = -10.50      # near line, camera side of the road\nCONTAINER_APRON_BACK_Y = -15.00  # far line of the apron block\nCONTAINER_ROWS = {\n    \"front\": CONTAINER_FRONT_Y,\n    \"back\": CONTAINER_BACK_Y,\n    \"apron\": CONTAINER_APRON_Y,\n    \"apron_back\": CONTAINER_APRON_BACK_Y,\n}\nCONTAINER_HEIGHT = 2.90     # the pack's boxes are all 2.9 m tall\n# The pack ships 22 whole 40 ft boxes (12.1 x 2.4 x 2.9) and 15 whole 20 ft\n# ones (6.4 x 2.4 x 2.9); everything else in it is a cut slice. Both lengths\n# are used so the yard is not one repeated box.\n#\n# (x of centre, row, nominal length, base z). A base z of 2.9 means the box is\n# stacked on the one below: the yard stacks two high in the back row only, so\n# the height reads as depth rather than as a wall next to the road.\nCONTAINER_LAYOUT = (\n    (-21.0, \"front\", \"40\", 0.0),\n    (-8.6, \"front\", \"40\", 0.0),\n    (4.2, \"front\", \"40\", 0.0),\n    (17.0, \"front\", \"40\", 0.0),\n    # A 14 m opening instead of a box at x = 29.9: a depot has aisles between\n    # blocks, and this one also lets the back row read through it, which is the\n    # cheapest depth cue in a shot that is otherwise one long wall.\n    (43.2, \"front\", \"40\", 0.0),\n    (56.3, \"front\", \"40\", 0.0),\n    (-14.8, \"back\", \"40\", 0.0),\n    (5.6, \"back\", \"40\", 0.0),\n    (5.6, \"back\", \"40\", CONTAINER_HEIGHT),\n    (24.4, \"back\", \"40\", 0.0),\n    (44.0, \"back\", \"40\", 0.0),\n    (41.0, \"back\", \"20\", CONTAINER_HEIGHT),   # 20 ft on the end of a 40 ft\n    # The apron block: two staggered lines, starting close enough to the camera\n    # that the right-hand ground has something in the foreground. The pitch\n    # wanders between 17 and 21 m on purpose -- an exact bay would read as a\n    # generated row, and this is the side of the shot the eye lands on when it\n    # has nothing else to do. The far line's boxes land in the near line's gaps.\n    (8.0, \"apron\", \"40\", 0.0),\n    (26.0, \"apron\", \"40\", 0.0),\n    (26.0, \"apron\", \"40\", CONTAINER_HEIGHT),\n    (47.0, \"apron\", \"40\", 0.0),\n    (65.0, \"apron\", \"40\", 0.0),\n    (85.0, \"apron\", \"40\", 0.0),\n    (106.0, \"apron\", \"40\", 0.0),\n    (106.0, \"apron\", \"20\", CONTAINER_HEIGHT),\n    (127.0, \"apron\", \"40\", 0.0),\n    (147.0, \"apron\", \"40\", 0.0),\n    (17.0, \"apron_back\", \"40\", 0.0),\n    (37.0, \"apron_back\", \"40\", 0.0),\n    (57.0, \"apron_back\", \"40\", 0.0),\n    (57.0, \"apron_back\", \"40\", CONTAINER_HEIGHT),\n    (78.0, \"apron_back\", \"40\", 0.0),\n    (99.0, \"apron_back\", \"40\", 0.0),\n    (120.0, \"apron_back\", \"40\", 0.0),\n    (141.0, \"apron_back\", \"40\", 0.0),\n)\n\n# How far a box's centre may sit off its row line, in metres. Both yard-side\n# rows are true to within 5 cm: they are set against a kerb. The apron block is\n# the one that is read almost edge-on, and a dead straight line of boxes 10.5 m\n# off the near kerb was the last thing in the shot that still looked generated\n# rather than parked, so those two rows are allowed to wander either way.\n# 1.5 m proved too polite: the two lines held a constant 4.5 m gap, so the eye\n# still read \"two rows\" with a wobble on them. At 2.2 m the near line sets back\n# anywhere from 4.7 m to 8.1 m off the kerb and the far line 9.1 m to 12.7 m,\n# so consecutive boxes step in and out by up to 3.4 m and every bay is at a\n# visibly different distance from the road. The bands still stop just short of\n# each other, so no rear box ever comes forward of a front one.\nROW_DEPTH_JITTER = {\n    \"front\": 0.05,\n    \"back\": 0.05,\n    \"apron\": 2.20,\n    \"apron_back\": 2.20,\n}\n\n# ---------------------------------------------------------------------- lamps\nLAMP_MODEL_HEIGHT = 5.46\nLAMP_TARGET_HEIGHT = 6.40\n# Yard lighting is laid out to light the apron, not to line the kerb. This row\n# has been thinned twice and the lesson from both passes is that pitch is the\n# wrong knob: a 6.4 m mast is still ~34 px tall at 240 m, so the far end of the\n# row never shrinks away -- it just piles up around the vanishing point and the\n# whole line keeps reading as a fence of posts no matter how far apart they\n# stand. At 36 m that pile-up was the complaint, so the row is now *shorter in\n# count* instead: 60 m between masts, 4 of them in shot.\n# The row still has to reach somewhere, though. An earlier version stopped at\n# x = 48 and the masts visibly ran out a third of the way to the horizon, which\n# is the same tell as a road that ends, so the last mast sits at x = 200, past\n# the point where the markings go sub-pixel.\nLAMP_XS = (-40.0, 20.0, 80.0, 140.0, 200.0)\nLAMP_Y = 5.00       # yard side of the kerb, same line the old masts stood on\n# There is deliberately no mast on the apron kerb: the block on that side is\n# read at a grazing angle, so a post in front of it became a foreground stick\n# with nothing to light, and the right-hand ground already has the container\n# block to carry its scale. `build_lamp_posts(arm_toward=+1)` is still able to\n# place one if that side ever needs lighting again.\n# The shot is late afternoon with the sun about 30 degrees up, so the posts are\n# switched off -- which is also what a working yard does. The asset ships with\n# its lens at emission strength 1.0 and the renderer used to hang a 520 W point\n# light under every head, which read as \"who left the lights on at noon\". Set\n# this True (and the caller will light them) for a dusk or night pass.\nLAMPS_LIT = False\n\n# ------------------------------------------------------------------ speed hump\nHUMP_MODEL_HALF_LENGTH = 0.60   # |x| where the model's profile reaches the road\nHUMP_MODEL_PEAK = 0.103\nHUMP_MODEL_HALF_WIDTH = 4.96\nHUMP_MODEL_CENTRE_Y = 3.475\n\n\ndef _import_glb(glb: Path) -> list[bpy.types.Object]:\n    before = set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(glb))\n    return [obj for obj in bpy.data.objects if obj not in before]\n\n\ndef _group(objs: list[bpy.types.Object], name: str) -> bpy.types.Object:\n    \"\"\"Parent the imported roots to a fresh empty without moving anything.\"\"\"\n    root = bpy.data.objects.new(name, None)\n    bpy.context.scene.collection.objects.link(root)\n    members = set(objs)\n    for obj in objs:\n        if obj.parent in members:\n            continue\n        world = obj.matrix_world.copy()\n        obj.parent = root\n        obj.matrix_world = world\n    return root\n\n\ndef _harvest_containers() -> tuple[list[bpy.types.Object], list[bpy.types.Object]]:\n    \"\"\"Import the pack and keep its intact boxes, in world space, split by length.\n\n    63 meshes, but only 37 of them are whole containers -- the rest are cut\n    boxes the pack uses to fill its own scene edges (0.5 x 1.1 x 2.8 m slices).\n    Placing those as if they were containers is what left 1 m gaps in the old\n    row. Returns ``(40 ft, 20 ft)`` so the layout table can pick a length per\n    slot instead of accepting whatever came first.\n    \"\"\"\n    objs = _import_glb(CONTAINER_PACK)\n    meshes = [obj for obj in objs if obj.type == \"MESH\"]\n    empties = [obj for obj in objs if obj.type != \"MESH\"]\n    forties: list[bpy.types.Object] = []\n    twenties: list[bpy.types.Object] = []\n    for obj in meshes:\n        lo, hi = _bbox_world(obj)\n        long_side = max(hi[0] - lo[0], hi[1] - lo[1])\n        if (hi[2] - lo[2]) < 2.0:\n            continue\n        if long_side > 10.0:\n            forties.append(obj)\n        elif long_side > 5.0:\n            twenties.append(obj)\n    keep = set(forties) | set(twenties)\n    for obj in meshes:\n        if obj not in keep:\n            bpy.data.objects.remove(obj, do_unlink=True)\n    for obj in empties:\n        bpy.data.objects.remove(obj, do_unlink=True)\n    for obj in keep:\n        world = obj.matrix_world.copy()\n        obj.parent = None\n        obj.matrix_world = world\n    return forties, twenties\n\n\ndef _bbox_world(obj: bpy.types.Object) -> tuple[list[float], list[float]]:\n    pts = [obj.matrix_world @ v.co for v in obj.data.vertices]\n    return (\n        [min(p[i] for p in pts) for i in range(3)],\n        [max(p[i] for p in pts) for i in range(3)],\n    )\n\n\ndef _yaw_about_centre(obj: bpy.types.Object, angle: float) -> None:\n    \"\"\"Turn ``obj`` about the vertical axis through its own bounding-box centre.\"\"\"\n    lo, hi = _bbox_world(obj)\n    centre = Vector(((lo[0] + hi[0]) * 0.5, (lo[1] + hi[1]) * 0.5, (lo[2] + hi[2]) * 0.5))\n    obj.matrix_world = (\n        Matrix.Translation(centre)\n        @ Matrix.Rotation(angle, 4, \"Z\")\n        @ Matrix.Translation(-centre)\n        @ obj.matrix_world\n    )\n\n\ndef _long_axis_is_x(obj: bpy.types.Object) -> bool:\n    lo, hi = _bbox_world(obj)\n    return (hi[0] - lo[0]) >= (hi[1] - lo[1])\n\n\ndef _place(obj: bpy.types.Object, x: float, y: float, z_base: float) -> tuple[float, float, float]:\n    \"\"\"Sit ``obj`` on ``z_base`` with its bbox centre over ``(x, y)``, long side to the road.\n\n    The layout table is written in road coordinates -- x along the haul road, y\n    away from it -- so a box whose long axis is authored along Y is turned a\n    quarter first. Returns the box's (length, depth, height) after the turn.\n    \"\"\"\n    if not _long_axis_is_x(obj):\n        _yaw_about_centre(obj, math.pi / 2.0)\n    lo, hi = _bbox_world(obj)\n    dims = (hi[0] - lo[0], hi[1] - lo[1], hi[2] - lo[2])\n    obj.matrix_world = (\n        Matrix.Translation(\n            (x - (lo[0] + hi[0]) * 0.5, y - (lo[1] + hi[1]) * 0.5, z_base - lo[2])\n        )\n        @ obj.matrix_world\n    )\n    return dims\n\n\ndef build_cargo_cartons(count: int = 2) -> list[bpy.types.Object]:\n    \"\"\"Import the parcel glb once and clone it for every cargo body.\n\n    The collider is a box of ``CARGO_HALF_EXTENTS``, so the picture only stays\n    honest if the mesh really is that box: the import is scaled by the single\n    factor ``CARGO_SCALE``, its bounding-box centre is moved to the origin, and\n    the transform is baked into the mesh. After that one object is a parcel\n    whose ``location`` is its centre -- the same quantity the simulation reports\n    -- and the clones are ``Object.copy()``, so all bodies share one mesh.\n    \"\"\"\n    asset = MODELS / cfg.CARGO_ASSET\n    imported = _import_glb(asset)\n    meshes = [obj for obj in imported if obj.type == \"MESH\"]\n    if not meshes:\n        raise RuntimeError(f\"{asset.name} imported no mesh\")\n    for obj in imported:\n        if obj.type != \"MESH\":\n            bpy.data.objects.remove(obj, do_unlink=True)\n\n    bpy.ops.object.select_all(action=\"DESELECT\")\n    for obj in meshes:\n        obj.select_set(True)\n    bpy.context.view_layer.objects.active = meshes[0]\n    if len(meshes) > 1:\n        bpy.ops.object.join()\n    proto = meshes[0]\n\n    lo, hi = _bbox_world(proto)\n    centre = Vector(((lo[i] + hi[i]) * 0.5 for i in range(3)))\n    proto.matrix_world = (\n        Matrix.Scale(cfg.CARGO_SCALE, 4) @ Matrix.Translation(-centre) @ proto.matrix_world\n    )\n    bpy.ops.object.select_all(action=\"DESELECT\")\n    proto.select_set(True)\n    bpy.context.view_layer.objects.active = proto\n    bpy.ops.object.transform_apply(location=True, rotation=True, scale=True)\n\n    # Cardboard, not the pack's default: the glb ships a mid-grey that reads as\n    # moulded plastic next to the truck's paint.\n    for slot in proto.material_slots:\n        if slot.material and slot.material.use_nodes:\n            for node in slot.material.node_tree.nodes:\n                if node.type == \"BSDF_PRINCIPLED\":\n                    node.inputs[\"Roughness\"].default_value = 0.82\n                    set_shader_input(node, 'Specular IOR Level', 0.28)\n\n    cartons = [proto]\n    for index in range(1, count):\n        clone = proto.copy()\n        bpy.context.scene.collection.objects.link(clone)\n        cartons.append(clone)\n    for index, obj in enumerate(cartons):\n        obj.name = f\"cargo_{index + 1}\"\n    return cartons\n\n\ndef _bay_hash(row: str, x: float) -> float:\n    \"\"\"Deterministic value in ``[-1, 1]`` for one bay of one row.\n\n    Keyed on ``(row, x)`` rather than on the loop index so a stacked box keeps\n    the placement and the yaw of the box it stands on: an index-keyed value\n    would slide the upper container up to three metres off the lower one.\n    \"\"\"\n    seed = int(round(float(x) * 10.0)) * 7919 + sum(ord(c) for c in row) * 104729\n    return ((seed * 2654435761) % 2003) / 1001.0 - 1.0\n\n\ndef build_container_yard() -> bpy.types.Object:\n    \"\"\"Lay the pack's intact boxes out as two rows behind the fence.\n\n    ``Object.copy()`` shares the mesh datablock, so a box reused twice costs one\n    transform and no geometry; the harvested originals are deleted afterwards so\n    the pack's own depot layout cannot leak into the shot.\n    \"\"\"\n    forties, twenties = _harvest_containers()\n    root = bpy.data.objects.new(\"container_yard\", None)\n    bpy.context.scene.collection.objects.link(root)\n\n    sources = {\"40\": forties, \"20\": twenties}\n    used = {\"40\": 0, \"20\": 0}\n    for index, (x, row, length, z_base) in enumerate(CONTAINER_LAYOUT):\n        pool = sources[length]\n        if not pool:\n            continue\n        source = pool[used[length] % len(pool)]\n        used[length] += 1\n        obj = source.copy()\n        obj.name = f\"container_{row}_{index:02d}\"\n        bpy.context.scene.collection.objects.link(obj)\n\n        # Deterministic jitter: a perfect grid is the loudest generated tell\n        # left, and no RNG keeps the render reproducible. Depth is the one that\n        # matters here -- how far the box sits from its kerb -- see\n        # ``ROW_DEPTH_JITTER``; a degree of yaw is what a box set down by a\n        # crane actually has, and the gaps in the table do the rest.\n        wobble = _bay_hash(row, x)\n        y = CONTAINER_ROWS[row] + wobble * ROW_DEPTH_JITTER[row]\n        _yaw_about_centre(obj, math.radians(wobble * 1.1))\n        _place(obj, x, y, z_base)\n        obj.parent = root\n\n    for obj in forties + twenties:\n        bpy.data.objects.remove(obj, do_unlink=True)\n    return root\n\n\ndef _unlit_lens(objs: list[bpy.types.Object]) -> None:\n    \"\"\"Drop the glb's emissive lamp lens so an unlit post really is unlit.\n\n    The asset authors the lens as white emission at strength 1.0, which in\n    daylight is a glowing panel on every post. Zeroing the strength keeps the\n    lens geometry and its base colour -- it reads as a plastic cover.\n    \"\"\"\n    for obj in objs:\n        if obj.type != \"MESH\":\n            continue\n        for slot in obj.material_slots:\n            mat = slot.material\n            if not mat or not mat.use_nodes:\n                continue\n            bsdf = next(\n                (n for n in mat.node_tree.nodes if n.type == \"BSDF_PRINCIPLED\"), None\n            )\n            if bsdf is None:\n                continue\n            strength = bsdf.inputs.get(\"Emission Strength\")\n            if strength is not None and not strength.is_linked:\n                strength.default_value = 0.0\n\n\ndef build_lamp_posts(\n    xs=LAMP_XS,\n    y: float = LAMP_Y,\n    height: float = LAMP_TARGET_HEIGHT,\n    arm_toward: float = -1.0,\n) -> list[tuple[float, float, float]]:\n    \"\"\"Place the downloaded post along a kerb line.\n\n    The asset's arm reaches +X, so the post is yawed a quarter turn to point it\n    across the road instead of down it. ``arm_toward`` is the *sign of Y* the\n    arm should reach: -1 on the yard kerb, where the road lies at y < 5, and +1\n    on the apron kerb on the camera side, where the road lies at y > -7.6.\n    Yawing both rows the same way is what leaves the apron posts lighting the\n    back of their own block, so the sign is carried through to the head offset\n    the caller hangs its point light on.\n    \"\"\"\n    factor = float(height) / LAMP_MODEL_HEIGHT\n    sign = 1.0 if arm_toward >= 0.0 else -1.0\n    heads: list[tuple[float, float, float]] = []\n    for index, x in enumerate(xs):\n        objs = _import_glb(LAMPPOST)\n        if not LAMPS_LIT:\n            _unlit_lens(objs)\n        root = _group(objs, f\"lamp_post_{index}\")\n        root.location = (float(x), float(y), 0.0)\n        root.rotation_euler = (0.0, 0.0, sign * math.pi / 2.0)\n        root.scale = (factor, factor, factor)\n        heads.append((float(x), float(y) + sign * 1.15 * factor, 5.05 * factor))\n    return heads\n\n\ndef build_speed_hump(\n    height: float, width: float, road_half_width: float\n) -> bpy.types.Object:\n    \"\"\"Skin the collider bump with the downloaded hump.\n\n    Three separate factors, each chosen against the collider rather than the\n    asset:\n\n    * X maps the model's ramp feet (|x| = 0.60) onto the collider's half width,\n      so the hump starts rising exactly where the collision profile does;\n    * Z puts the model's 0.103 m plateau on the requested peak height;\n    * Y spans the visible road width.\n\n    The model's top is flatter than a sine, so mid-slope it sits up to ~26 mm\n    above the collision profile -- the tyre sinks into the hump by that much\n    instead of floating over it, which is the error that reads correctly.\n    \"\"\"\n    objs = _import_glb(SPEED_HUMP)\n    root = _group(objs, \"speed_hump\")\n    root.scale = (\n        (float(width) * 0.5) / HUMP_MODEL_HALF_LENGTH,\n        (2.0 * float(road_half_width)) / (2.0 * HUMP_MODEL_HALF_WIDTH),\n        float(height) / HUMP_MODEL_PEAK,\n    )\n    root.location = (\n        cfg.SPEED_BUMP_CENTER_X,\n        -HUMP_MODEL_CENTRE_Y * root.scale[1],\n        0.0,\n    )\n    return root\n", "import_truck": "\"\"\"Adapt the desktop CC-BY truck to the benchmark's chassis/deck rig.\n\nThe glb is a real-proportioned three-axle flatbed authored at 26.03 x 8.87 x\n8.86 model units. It is *not* a 1:1 asset -- it is a real truck blown up to\nroughly 3.4x life size, so every proportion is right and the absolute size is\nnot. This adapter therefore applies exactly one factor to it, ``scale``, on all\nthree axes::\n\n    X = cfg.model_x(p.y)      Y = p.x * scale      Z = cfg.model_z(p.z)\n\n``cfg.TRUCK_SCALE`` is that factor and ``cfg.model_x`` / ``cfg.model_z`` are the\nsame two functions the collision rig is built from, so the visible mesh and the\ncollider cannot disagree -- if the deck plank moves, the box the cargo rests on\nmoves with it. Nothing is stretched along a single axis: an earlier version\ncorbelled the 0.70 m between the model's sill and its bed into one band so the\ndeck could stay at 1.25 m, which is exactly what made the cab read as mounted on\nstilts. The rig follows the model instead, so the deck sits at 0.737 m.\n\nThe one part that is not simply ``scale`` is the tyre: the rig models a single\nwheel radius (``cfg.WHEEL_RADIUS``), which is the front tyre's 1.635 units times\n``scale``. The front tyres therefore land exactly, and the narrower rear tandem\n(1.489 units) is scaled up by 9.8 % so all six tyres can stand on the road. The\nfront axle is the one that strikes the bump, so the contact that matters is\nexact.\n\nMaterials: the glb's paint map is a near-white panel sheet with rust along the\nseams (see ``assets/models/flatbed_unity3d.glb`` image 0), and its paint\nmaterial is glTF ``roughness 0.0`` -- a mirror. The dark olive on the published\npage is that mirror reflecting a dark environment, not a colour in the texture.\nThe tint below reproduces it by multiplying the map, so the grime survives, and\n``PAINT_ROUGHNESS`` makes it read as paint rather than chrome.\n\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nfrom pathlib import Path\n\nimport bpy\nfrom mathutils import Vector\n\nimport scene_support.flatbed_speed_bump.scene_config as cfg\n\nASSET = _PCVE_ROOT / 'assets' / 'models' / 'flatbed_unity3d.glb'\n\n# Multiplied into the paint map: a near-white base with baked rust streaks\n# becomes the dark olive the published model shows, streaks and panel dirt\n# intact.\nPAINT_TINT = (0.30, 0.32, 0.20)\nPAINT_ROUGHNESS = 0.34\nWHEEL_ROUGHNESS = 0.52\n\n\ndef _bbox(points):\n    lo = Vector(tuple(min(p[i] for p in points) for i in range(3)))\n    hi = Vector(tuple(max(p[i] for p in points) for i in range(3)))\n    return lo, hi, (lo + hi) * 0.5\n\n\ndef _tint_base_color(mat, tint) -> None:\n    \"\"\"Multiply ``mat``'s base-colour map by ``tint`` (the map is kept).\"\"\"\n    if not mat or not mat.use_nodes:\n        return\n    nodes = mat.node_tree.nodes\n    links = mat.node_tree.links\n    bsdf = next((n for n in nodes if n.type == 'BSDF_PRINCIPLED'), None)\n    if bsdf is None or not bsdf.inputs['Base Color'].is_linked:\n        return\n    source = bsdf.inputs['Base Color'].links[0].from_socket\n    mix = nodes.new('ShaderNodeMix')\n    mix.name = 'paint_tint'\n    mix.data_type = 'RGBA'\n    mix.blend_type = 'MULTIPLY'\n    mix.clamp_factor = True\n    sockets = {s.identifier: s for s in mix.inputs}\n    factor = sockets.get('Factor_Float') or mix.inputs[0]\n    factor.default_value = 1.0\n    color_a = sockets.get('A_Color') or mix.inputs[6]\n    color_b = sockets.get('B_Color') or mix.inputs[7]\n    color_b.default_value = (tint[0], tint[1], tint[2], 1.0)\n    result = next((s for s in mix.outputs if s.identifier == 'Result_Color'), mix.outputs[2])\n    links.new(source, color_a)\n    links.new(result, bsdf.inputs['Base Color'])\n\n\ndef build_truck(asset=None):\n    source = Path(asset) if asset else ASSET\n    if not source.is_file():\n        raise FileNotFoundError(f\"Required truck model not found: {source}\")\n    bpy.ops.import_scene.gltf(filepath=str(source))\n    imported = list(bpy.context.selected_objects)\n    bpy.context.view_layer.update()\n    meshes = [o for o in imported if o.type == 'MESH']\n    baked = [(o, [o.matrix_world @ v.co for v in o.data.vertices]) for o in meshes]\n    for o in meshes:\n        o.parent = None\n        o.matrix_world.identity()\n    for o in imported:\n        if o.type != 'MESH':\n            bpy.data.objects.remove(o, do_unlink=True)\n\n    # --- wheel inventory: axle positions drive every later anchor ----------\n    wheel_info = {}\n    for obj, points in baked:\n        if 'Wheel' in obj.name and points:\n            lo, hi, centre = _bbox(points)\n            wheel_info[obj.name] = (lo, hi, centre)\n    front = [c.y for n, (_lo, _hi, c) in wheel_info.items() if 'F_Wheel' in n]\n    rear = [c.y for n, (_lo, _hi, c) in wheel_info.items() if 'F_Wheel' not in n]\n    if not front or not rear:\n        raise RuntimeError('flatbed glb: expected front and rear wheels by name')\n\n    scale = cfg.TRUCK_SCALE\n    # The rig's axle spacing is ``scale`` times the model's by construction;\n    # check it here so a swapped asset fails loudly instead of importing with a\n    # silently wrong wheelbase.\n    model_spread = abs(sum(front) / len(front) - sum(rear) / len(rear))\n    if abs(model_spread * scale - cfg.WHEEL_BASE) > 1e-3:\n        raise RuntimeError(\n            f'flatbed glb: axle spread {model_spread:.4f} x {scale:.6f} = '\n            f'{model_spread * scale:.4f} m, rig has {cfg.WHEEL_BASE:.4f} m'\n        )\n\n    def to_vehicle(p: Vector) -> Vector:\n        \"\"\"Model units -> vehicle frame (road at -R, axle line at 0, nose +X).\"\"\"\n        return Vector((\n            cfg.model_x(p.y),\n            p.x * scale,\n            cfg.model_z(p.z),\n        ))\n\n    chassis = bpy.data.objects.new('truck_chassis', None)\n    deck = bpy.data.objects.new('truck_deck', None)\n    bpy.context.collection.objects.link(chassis)\n    bpy.context.collection.objects.link(deck)\n\n    wheels = []\n    for obj, points in baked:\n        if obj.name in wheel_info:\n            lo, hi, centre = wheel_info[obj.name]\n            # The rig has one wheel radius; the front tyre is the exact one, the\n            # rear tandem is 9.8 % larger (see the module docstring).\n            wheel_scale = cfg.WHEEL_RADIUS / ((hi.z - lo.z) * 0.5)\n            radius = (hi.z - lo.z) * 0.5 * wheel_scale\n            position = to_vehicle(centre)\n            pivot = bpy.data.objects.new(obj.name + '_axle', None)\n            bpy.context.collection.objects.link(pivot)\n            pivot.parent = chassis\n            # The tyre has to meet the road: its centre goes on the physics axle\n            # line, not where the body warp would have put it.\n            pivot.location = (position.x, position.y, -cfg.CHASSIS_COM_Z)\n            pivot['rolling_radius'] = radius\n            obj.parent = pivot\n            for v, p in zip(obj.data.vertices, points):\n                q = p - centre\n                # The model's axle runs along X; the pivot spins about its own Y.\n                v.co = (-q.y * wheel_scale, q.x * wheel_scale, q.z * wheel_scale)\n            wheels.append(pivot)\n        else:\n            obj.parent = chassis\n            for v, p in zip(obj.data.vertices, points):\n                vehicle = to_vehicle(p)\n                v.co = (vehicle.x, vehicle.y, vehicle.z - cfg.CHASSIS_COM_Z)\n            # Split the bed from the cab so the original suspension still works.\n            # Faces behind the cab and above the sill belong to the bed.\n            bed_faces = [poly.index for poly in obj.data.polygons if all(\n                points[i].y > cfg.MODEL_BED_FRONT_Y and points[i].z > cfg.MODEL_BED_SILL_Z\n                for i in poly.vertices)]\n            if bed_faces:\n                bpy.ops.object.select_all(action='DESELECT')\n                obj.select_set(True)\n                bpy.context.view_layer.objects.active = obj\n                bpy.ops.object.mode_set(mode='EDIT')\n                bpy.ops.mesh.select_all(action='DESELECT')\n                bpy.ops.object.mode_set(mode='OBJECT')\n                for index in bed_faces:\n                    obj.data.polygons[index].select = True\n                bpy.ops.object.mode_set(mode='EDIT')\n                bpy.ops.mesh.separate(type='SELECTED')\n                bpy.ops.object.mode_set(mode='OBJECT')\n                for part in list(bpy.context.selected_objects):\n                    if part != obj:\n                        part.name = 'imported_sprung_' + part.name\n                        part.parent = deck\n                        for v in part.data.vertices:\n                            v.co -= Vector((\n                                cfg.DECK_CENTER_X, 0,\n                                cfg.DECK_Z - cfg.CHASSIS_COM_Z,\n                            ))\n        for mat in obj.data.materials:\n            if mat and mat.use_nodes:\n                bsdf = next((n for n in mat.node_tree.nodes\n                             if n.type == 'BSDF_PRINCIPLED'), None)\n                if bsdf is None:\n                    continue\n                if 'Paint' in mat.name:\n                    bsdf.inputs['Roughness'].default_value = PAINT_ROUGHNESS\n                    _tint_base_color(mat, PAINT_TINT)\n                elif 'Wheel' in mat.name:\n                    bsdf.inputs['Roughness'].default_value = WHEEL_ROUGHNESS\n                else:\n                    bsdf.inputs['Roughness'].default_value = 0.40\n    return chassis, deck, wheels\n", "runtime_support": "\"\"\"Local runtime discovery; scripts also work in ordinary Python/Blender installs.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport os\nimport sys\nfrom pathlib import Path\n\nROOT = _PCVE_ROOT\n_dll_handles = []\nif os.name == \"nt\":\n    directory = Path(sys.prefix) / \"Library/bin\"\n    if directory.exists():\n        _dll_handles.append(os.add_dll_directory(str(directory)))\n\n\ndef python_for(role):\n    sys.path.insert(0, str(ROOT/'clean_scripts'))\n    from pcve_scene_runtime import python_for as resolve_python\n    return resolve_python(role)\n", "scene_config": "\"\"\"Shared geometry and baseline parameters for the flatbed-speed-bump scene.\n\nBoth the PyBullet simulation and the Blender renderer import these constants so\nthe collision shapes and the visible meshes cannot drift apart, and so the\nscene's three exposed controls have exactly one definition.\n\nWorld conventions\n-----------------\n* The truck is driven along world **+X**; the cab faces +X.\n* **+Y** is the far kerb (the freight-yard side); **-Y** is the near kerb\n  (safety fence, cones) that faces the camera.\n* Everything about the truck is expressed in the **vehicle reference frame\n  V**: the origin sits on the wheel-axle line at mid-wheelbase, i.e.\n  ``WHEEL_RADIUS`` above the road, so ``V z = 0`` is the axle height and the\n  road surface is at ``V z = -WHEEL_RADIUS``. Chassis-local coordinates are\n  V-relative values shifted by ``-CHASSIS_COM_Z``, because a multibody's base\n  position *is* its centre of mass.\n\nWhy the bed is its own body\n---------------------------\nA rigid truck that clears a speed bump flies as one piece, and so does\nanything resting on it: while the vehicle is ballistic the bed and its cargo\nshare exactly the same acceleration, so the cargo can never leave the bed no\nmatter how violent the jump looks. Making the deck a *sprung* body on a\nprismatic suspension is what actually throws the cargo: the deck overshoots the\nchassis and can be pulled down at well over 1 g on the rebound, which is the\none condition under which a loose carton separates from it.\n\"\"\"\n\nfrom __future__ import annotations\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\n# --------------------------------------------------------------------- truck\n#\n# The rig is *derived from* the asset, not fitted to it. ``flatbed_unity3d.glb``\n# is a real-proportioned three-axle flatbed authored at 26.03 x 8.87 x 8.86\n# model units, and it is placed by ONE factor, ``TRUCK_SCALE``, applied to every\n# vertex on all three axes -- ``model_x`` / ``model_z`` below plus\n# ``p.x * TRUCK_SCALE`` are the whole mapping, and ``import_truck`` calls the\n# same two functions. There is no per-axis correction left anywhere, so every\n# proportion the artist built survives.\n#\n# That is why the deck sits at 0.737 m and the wheelbase is 3.068 m instead of\n# at round numbers: those are where this truck's bed and axles actually are. Any\n# rig that wants the deck higher has to stretch the 0.70 m between the sill and\n# the bed, and that stretch is exactly what reads as \"the cab is on stilts\".\n#\n# The factor itself is the front tyre radius over the rig's, which keeps the\n# 0.34 m wheel: the 0.17 m bump therefore stays at half a wheel radius and the\n# suspension keeps being excited in the band it was tuned for.\n\n# Measured on the asset, in model units (_dump_truck_dimensions.py prints them).\nMODEL_GROUND_Z = -4.43          # tyre contact plane\nMODEL_WHEEL_R = 1.635           # front tyre radius\nMODEL_FRONT_AXLE_Y = -11.2425\nMODEL_REAR_AXLE_Y = 3.5119      # mean of the rear tandem\nMODEL_BED_TOP_Z = -0.887        # up-facing deck plank, level with the tyre tops\nMODEL_BED_FRONT_Y = -6.46       # nose end of the deck, where the cab ends\nMODEL_BED_SILL_Z = -1.23        # lowest bed face; below this it is still frame\nMODEL_BED_Y = (-6.45, 9.64)\nMODEL_BED_X = (-4.11, 4.09)\nMODEL_CAB_Y = (-16.39, -6.51)\nMODEL_CAB_X = (-4.46, 4.41)\nMODEL_CAB_Z = (-1.23, 4.43)\nMODEL_FRAME_Y = (-15.75, 9.57)\nMODEL_FRAME_X = (-4.15, 4.13)\n\nTRUCK_SCALE = 0.34 / MODEL_WHEEL_R                    # 0.2079511\n\nWHEEL_RADIUS = MODEL_WHEEL_R * TRUCK_SCALE            # 0.3400\nWHEEL_WIDTH = 1.437 * TRUCK_SCALE                     # 0.2988, front tyre\nWHEEL_BASE = (MODEL_REAR_AXLE_Y - MODEL_FRONT_AXLE_Y) * TRUCK_SCALE\nWHEEL_XS = (-0.5 * WHEEL_BASE, 0.5 * WHEEL_BASE)      # 3.0682 m axle spacing\n# The front axle strikes the bump first, so its track is what the four collision\n# cylinders use; the rear tandem is narrower (0.591 m half-track) and only its\n# visible wheels sit there.\nWHEEL_YS = (-3.398 * TRUCK_SCALE, 3.398 * TRUCK_SCALE)  # 1.4132 m track\n\n\ndef model_x(y: float) -> float:\n    \"\"\"Model +Y (rearwards) -> vehicle X, front axle on ``+WHEEL_BASE / 2``.\"\"\"\n    return 0.5 * WHEEL_BASE - (y - MODEL_FRONT_AXLE_Y) * TRUCK_SCALE\n\n\ndef model_z(z: float) -> float:\n    \"\"\"Model +Z -> vehicle Z, with the tyre contact patch landing on ``-R``.\"\"\"\n    return -WHEEL_RADIUS + (z - MODEL_GROUND_Z) * TRUCK_SCALE\n\n\n# The chassis body's origin is its centre of mass, placed this high above the\n# ground contact line; the collision shapes below are offset from it. 0.55 m is\n# the height the pitch and roll response was tuned at, and the tyre radius is\n# unchanged, so it stays.\nCHASSIS_MASS = 900.0\nCHASSIS_COM_Z = 0.55\n# Underbody rail, cut off at the axle line. The model's sill reaches down to\n# 0.108 m above the road, which is below the 0.17 m bump crest -- a collider\n# that deep would ride up on the bump, so the box stops at V z = 0. The sim\n# centres this box on X = 0 while the model's own rail is 0.16 m off-centre, so\n# it takes the shorter side: that keeps it inside the body at both ends.\nFRAME_HALF = (\n    min(abs(model_x(MODEL_FRAME_Y[0])), abs(model_x(MODEL_FRAME_Y[1]))),\n    0.5 * (MODEL_FRAME_X[1] - MODEL_FRAME_X[0]) * TRUCK_SCALE,\n    0.125,\n)\nFRAME_Z = 0.125\n# The cab's collision box starts behind the deck's front edge only if it is\n# pushed far enough forward: an overlapping box would press on the deck and\n# lock the suspension solid at zero travel. Here the model's own gap (12 mm) is\n# what separates them; the joint is prismatic in Z, so the deck cannot rotate\n# into the cab.\nCAB_HALF = (\n    abs(0.5 * (model_x(MODEL_CAB_Y[1]) - model_x(MODEL_CAB_Y[0]))),\n    0.5 * (MODEL_CAB_X[1] - MODEL_CAB_X[0]) * TRUCK_SCALE,\n    0.5 * (model_z(MODEL_CAB_Z[1]) - model_z(MODEL_CAB_Z[0])),\n)\nCAB_X = 0.5 * (model_x(MODEL_CAB_Y[1]) + model_x(MODEL_CAB_Y[0]))\nCAB_Z = 0.5 * (model_z(MODEL_CAB_Z[1]) + model_z(MODEL_CAB_Z[0]))\n\n# ------------------------------------------------------- sprung flatbed deck\n\nBED_MASS = 350.0\nDECK_HALF = (\n    abs(0.5 * (model_x(MODEL_BED_Y[1]) - model_x(MODEL_BED_Y[0]))),\n    0.5 * (MODEL_BED_X[1] - MODEL_BED_X[0]) * TRUCK_SCALE,\n    # A 50 mm plate: thin enough to hide inside the model's bed slab, which is\n    # 0.071 m thick at this scale, so the 0.05 m of collision below the plank\n    # surface never pokes out under the visible sill.\n    0.025,\n)\nDECK_CENTER_X = 0.5 * (model_x(MODEL_BED_Y[1]) + model_x(MODEL_BED_Y[0]))\nDECK_TOP_Z = model_z(MODEL_BED_TOP_Z)     # V-frame deck surface, 0.3968\nDECK_Z = DECK_TOP_Z - DECK_HALF[2]        # V-frame centre of the deck at rest\nDECK_FRONT_X = DECK_CENTER_X + DECK_HALF[0]\nDECK_REAR_X = DECK_CENTER_X - DECK_HALF[0]\n\n# Prismatic travel of the deck on the chassis: down is compression, up is droop.\n# Down is capped by the 0.097 m between the deck plate and the frame top.\nSUSPENSION_TRAVEL_DOWN = 0.09\nSUSPENSION_TRAVEL_UP = 0.07\n# 40 kN/m on the 350 kg deck is 1.70 Hz. That is far softer than the 280 kN/m\n# the 2.28 m rig used, and it has to be: what a chassis feeds the deck is the\n# gap between the two axles clearing the bump, and this wheelbase is 3.068 m\n# rather than 2.28 m, i.e. 2.9 Hz instead of 3.9 Hz. A deck stiff enough to\n# follow the chassis over the bump just rides with it, and then the cargo shares\n# its acceleration and never leaves the planks. `_sweep_suspension.py` over\n# 40-280 kN/m x damping ratio 0.12/0.25/0.35 put the launch peak here: 65 mm of\n# deck clearance and 7 airborne frames, against 40 mm and 3 at 280 kN/m.\nSUSPENSION_STIFFNESS = 40_000.0\nSUSPENSION_DAMPING = 1_870.0\n# Bump and droop stops: a stiffer one-sided spring takes over past the travel\n# limits, which is what keeps the deck from driving into the frame.\nSTOP_STIFFNESS = 700_000.0\nSTOP_DAMPING = 6_000.0\n# Hard cap on what the suspension may transmit, as a multiple of the deck's\n# weight. This is what keeps the explicit integration stable when the chassis\n# lands hard: uncapped, a 0.16 m bump sent the deck's travel into the tens of\n# metres.\nSUSPENSION_FORCE_LIMIT_UP = 14.0\nSUSPENSION_FORCE_LIMIT_DOWN = 4.0\n\nCHASSIS_ANGULAR_DAMPING = 0.12\n# The wheels are cylinders fixed to the chassis; they have no axle of their own\n# and cannot spin, so any real Coulomb coefficient turns them into skids that\n# stop the truck (about 0.96 g) long before it reaches the bump. Giving them a\n# near-frictionless contact is what a free-rolling tyre actually looks like\n# here: it still carries the full normal load, so the bump still kicks the\n# truck, it just does not drag.\nWHEEL_ROAD_FRICTION = 0.02\n# Cruise control, as a real force applied at the chassis centre of mass rather\n# than a velocity override. The override was the one thing that made this scene\n# unphysical: resetting the linear velocity every substep threw away the contact\n# impulse's linear part while keeping its angular part, which pumped angular\n# momentum into the chassis and stood the truck on its tail -- an 87 degree\n# wheelie on bumps as small as 0.10 m. A force at the centre of mass cannot\n# torque the chassis, so the pitch it produces is only what the bump really\n# produces.\nDRIVE_FORCE_GAIN = 200_000.0       # N per m/s of speed error\nDRIVE_FORCE_MAX = 25_000.0         # N, about 18 m/s^2 on the laden truck\n\n# ------------------------------------------------------------------- cargo\n# Two identical parcels ride loose on the bed, abreast and almost touching:\n# side by side across the deck, parallel to its long axis, 8 mm apart. The gap\n# is not decorative -- spawning them truly coincident makes Bullet fire a\n# separation impulse on frame 1 -- but it is small enough that the pair reads as\n# one tidy load instead of two boxes parked at random.\n#\n# The parcel is the ``carton_box_05_closed`` glb, measured at 31.5488 x 39.9721\n# x 25.8244 model units with its base on z = 0 (see ``_dump_asset_bounds.py``).\n# One factor takes that to a real parcel: CARGO_SCALE puts the 25.82 height at\n# 0.52 m -- the height the old procedural crate had, so the suspension tuning\n# and the 0.20 friction band still describe the same load. x and y are *not*\n# chosen, they follow the model's own 1.222 : 1.548 : 1 aspect, which is why\n# the footprint comes out 0.635 x 0.805 instead of the old 0.64 x 0.56.\n\nCARGO_ASSET = \"carton_box_05_closed.glb\"\nCARGO_MODEL_SIZE = (31.5488, 39.9721, 25.8244)\nCARGO_TARGET_HEIGHT = 0.52\nCARGO_SCALE = CARGO_TARGET_HEIGHT / CARGO_MODEL_SIZE[2]          # 0.0201362\nCARGO_SIZE = tuple(size * CARGO_SCALE for size in CARGO_MODEL_SIZE)\n\nCARGO_HALF_EXTENTS = (\n    tuple(0.5 * size for size in CARGO_SIZE),                    # 0.3176 x 0.4024 x 0.26\n    tuple(0.5 * size for size in CARGO_SIZE),\n)\n# The pair is abreast in Y but staggered in X by 0.90 m, and the near-side\n# parcel (index 0, -Y, the camera side) is the one set back: its rear face is\n# 0.65 m from the tail edge of the planks, and its centre of mass is 0.97 m\n# from it. That is the whole point of the scene now. The deck lags the chassis\n# on the rebound and the loose parcel lags the deck, so in deck coordinates it\n# travels aft during the strike; mid-deck that aft travel is all spent sliding\n# on the planks, and moving the pair to the tail converts the same aft travel\n# into a parcel going over the back edge while the far parcel rides it out as\n# the control.\n#\n# Both numbers are measured, not chosen, and `_probe_cargo_xs.py` is the\n# measurement: it walks one parcel at a time and reports whether it is still\n# aboard at t = 4 s. The aft slip is 1.0-1.5 m in deck coordinates, so a parcel\n# has to start within ~1.0 m of the tail edge to go over, and the other has to\n# start at least ~1.85 m from it to survive -- which is why the two cannot sit\n# at the same x and why the stagger is 0.9 m rather than the \"just slightly\n# back\" a still frame would suggest. At this split the near parcel leaves at\n# the 9 m/s baseline and still leaves at 7 m/s; the far one does not leave at\n# either, which is what makes the shot readable: one parcel on the road, one\n# still on the planks.\nCARGO_DECK_LOCAL_XS = (-0.70, 0.20)    # deck-local x; -X is aft, 0 = deck centre\nCARGO_GAP_Y = 0.008                     # mm-scale only: see the note above\nCARGO_LOCAL_XS = tuple(DECK_CENTER_X + x for x in CARGO_DECK_LOCAL_XS)\nCARGO_LOCAL_YS = (\n    -(CARGO_HALF_EXTENTS[0][1] + 0.5 * CARGO_GAP_Y),   # near kerb, set back\n    +(CARGO_HALF_EXTENTS[0][1] + 0.5 * CARGO_GAP_Y),   # far kerb, forward\n)\n\n# --------------------------------------------------------------- speed bump\n# A rounded (sine-profile) bump spanning the full road width. Its width stays\n# below the truck's wheelbase, so the two axles strike it separately and the\n# bed is pitched as well as heaved.\n\nSPEED_BUMP_CENTER_X = 0.0\nSPEED_BUMP_WIDTH = 1.34\nSPEED_BUMP_SEGMENTS = 24\n\n# ------------------------------------------------------------------- roadway\n\nROAD_HALF_LENGTH = 70.0\nROAD_HALF_WIDTH = 4.0\nROAD_SURFACE_Z = 0.0\n\n# Truck spawn: far enough back that the approach, the strike, the flight and\n# the landing all fit inside one short clip.\nTRUCK_START_X = -7.0\n\n# ---------------------------------------------------------------- baseline\n\n# The three controls the benchmark exposes, plus the surfaces that are\n# deliberately fixed so a single-variable edit really is single-variable.\nBASELINE_PHYSICS = {\n    \"truck_speed\": 9.0,          # m/s -- about 32 km/h, deliberately too fast\n    \"speed_bump_height\": 0.17,   # m   -- peak height of the rounded bump\n    # 0.20 sits in the middle of the band that matters: below it the cartons\n    # skid off the deck, above it they grip and stay, so both directions of the\n    # edit read as different outcomes. At 0.34 the high side had already\n    # saturated.\n    \"cargo_friction\": 0.20,      # --  cargo box <-> deck pair friction\n}\nFIXED_PHYSICS = {\n    \"deck_friction\": 0.70,       # the deck's own coefficient; the pair with the\n                                 # cargo is what the exposed knob scales\n    \"road_friction\": 0.96,\n    \"cargo_mass\": 42.0,\n    \"gravity_z\": -9.8,\n}\n\n# The camera is a fixed vantage on the near-kerb side of the road, so the truck\n# drives through the frame instead of the frame driving with it. A chase rig\n# would hold the truck still on screen and read the throw only as background\n# motion, which hides the one thing the scene exists to show. It sits on the -Y\n# (camera-facing) side and is framed *left*: the start of the run (the truck\n# intact at x = -7) must be fully in frame, and only the stretch the truck needs\n# to clear the bump matters -- the empty haul road past the landing is left out\n# of shot, so no dead runway dominates the right half of the frame.\nSTATIC_CAMERA_LOCATION = (0.0, -12.0, 3.3)\nSTATIC_CAMERA_TARGET = (1.0, 0.0, 1.15)\nSTATIC_CAMERA_LENS_MM = 26.0\n\nBASELINE_RENDER = {\n    \"fps\": 24,\n    \"duration_sec\": 4.0,\n    # Matches the other rigid-body suites in this repo. EEVEE Next holds about\n    # 14 s per frame here at 960x540/32, so a full clip is roughly 18 minutes;\n    # 1280x720/48 is about three times that for no visible gain.\n    \"resolution\": (960, 540),\n    \"samples\": 32,\n    # The clip is a bolted-down camera by requirement, so it has to hold a run\n    # of 41 m: see ``render_flatbed_speed_bump.CAMERA_PRESETS``. ``static`` only\n    # works for one still.\n    \"camera_mode\": \"clip4s\",\n}\n\n# ------------------------------------------------------------------ helpers\n\n\ndef bed_rest_top_z() -> float:\n    \"\"\"World z of the deck surface with the truck sitting at rest.\"\"\"\n    return WHEEL_RADIUS + DECK_TOP_Z\n\n\ndef road_length_for(speed: float, duration_sec: float, *, margin: float = 12.0) -> float:\n    \"\"\"Half-length that keeps a truck at ``speed`` on the slab for the clip.\"\"\"\n    reach = abs(float(TRUCK_START_X)) + abs(float(speed)) * float(duration_sec) + margin\n    return max(ROAD_HALF_LENGTH, reach)\n", "flatbed_speed_bump.cache_contract": "\"\"\"Compatibility contract for flatbed trajectories and renderer replays.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport hashlib,json\nfrom pathlib import Path\ndef _scene_directory():\n    scripts_root = _PCVE_ROOT / 'clean_scripts'\n    for candidate in (scripts_root / \"rigid_rigid\" / \"flatbed_speed_bump\", scripts_root / \"flatbed_speed_bump\"):\n        if candidate.is_dir():\n            return candidate\n    raise FileNotFoundError(\"Scene directory not found for flatbed_speed_bump\")\n\n\nCACHE_SCHEMA_VERSION=4\n\ndef signature(parameters):\n    import hashlib, json\n    scene_dir = _PCVE_SCENE_ROOT\n    common_dir = _PCVE_ROOT / \"clean_scripts\"\n    files = list(scene_dir.glob(\"*.py\")) + list(common_dir.glob(\"*.py\"))\n    implementation = {str(path.relative_to(_PCVE_ROOT)): hashlib.sha256(path.read_bytes()).hexdigest()\n                      for path in files if path.is_file()}\n    payload = dict(implementation=implementation, scenario=parameters)\n    return hashlib.sha256(json.dumps(payload, sort_keys=True, allow_nan=False, default=str).encode()).hexdigest()\ndef validate_cache(data,requested=None):\n    message='Incompatible flatbed physics cache: parameters, geometry or implementation changed; resimulate first.'\n    if data.get('schema_version')!=CACHE_SCHEMA_VERSION or data.get('scene')!='flatbed_speed_bump':raise ValueError(message)\n    params=data.get('simulation_parameters',{})\n    if data.get('simulation_signature')!=signature(params):raise ValueError(message)\n    for name,value in (requested or {}).items():\n        if value is not None and params.get(name)!=value:raise ValueError(message+' Mismatch: '+name)\n    count=max(2,round(params['fps']*params['duration_sec']))\n    if data.get('fps')!=params['fps'] or data.get('duration_sec')!=params['duration_sec'] or data.get('frame_end')!=count or len(data.get('frames',[]))!=count:raise ValueError(message)\n    for name,value in data['physics_parameters'].items():\n        if name in params and value!=params[name]:raise ValueError(message)\n", "flatbed_speed_bump.import_props": "\"\"\"Import the downloaded props: containers, lamp posts, speed hump, parcels.\n\nNone of these are physics bodies except the parcels, which are the *picture* of\ncargo bodies the simulation owns; the rest never appear in the ground truth.\nThree are placed at their authored size, **unscaled**:\n\n* the containers are real 12.1 / 6.4 x 2.4 x 2.9 m boxes, turned and shifted\n  only, laid out as two rows with their long sides to the road (see\n  ``CONTAINER_LAYOUT``);\n* the lamp posts are a single uniform 1.172x, because 6.40 m is the height the\n  lighting rig was built around and a lamp post is one rigid object.\n\nThe speed hump is the one non-uniform placement in the scene, and it is not a\nprop: it is the *picture* of a collider that already exists as a sine profile in\n``scene_config``. Its three factors map the model's ramp feet onto the\ncollider's half width, its 0.103 m plateau onto the requested peak, and its\n9.92 m span onto the 8 m road. A single factor cannot do all three -- at the\nwidth factor it would be 0.083 m tall, so the truck would visibly ride 87 mm\nabove the hump it is colliding with; at the height factor it would be 16.4 m\nwide, twice the road. Nothing here is animated, so no vertex-level adapter like\n``import_truck`` is needed.\n\nMeasured from the glbs (glTF units are metres):\n\n* ``container_pack`` -- a whole depot, 29.8 x 43.2 x 8.8 m, 63 meshes, 40 ft\n  boxes at 12.06 x 2.42 x 2.92 m stacked up to three high, ground plane at\n  z = 0. Long axis along +X, so the boxes present their long sides to the road.\n* ``lamppost`` -- one 5.46 m post, arm reaching +X to x = 1.25, base at z = 0.\n* ``speed_bump`` -- one hump, 2.0 m along X (the travel direction), 9.92 m\n  along Y, plateau at z = +0.103, moulded skirt down to z = -0.208. It goes\n  flat at |x| ~ 0.60 and peaks across |x| < 0.15.\n* ``carton_box_05_closed`` -- one parcel, 31.5488 x 39.9721 x 25.8244 model\n  units, centred on x = y = 0 with its base on z = 0. Unlike the three above it\n  is scaled, by the single ``CARGO_SCALE`` factor, because it has to match a\n  box collider whose half extents the simulation owns.\n\"\"\"\n\nfrom __future__ import annotations\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\nimport sys\nfrom pathlib import Path\nsys.path.insert(0, str(_PCVE_ROOT / 'clean_scripts'))\nfrom pcve_blender_compat import (shader_socket, set_shader_input, eevee_engine, set_eevee_property, set_color_property)\n\nimport math\nfrom pathlib import Path\n\nimport bpy\nfrom mathutils import Matrix, Vector\n\nimport scene_support.flatbed_speed_bump.scene_config as cfg\n\nMODELS = _PCVE_ROOT / \"assets\" / \"models\"\nCONTAINER_PACK = MODELS / \"container_pack.glb\"\nLAMPPOST = MODELS / \"lamppost.glb\"\nSPEED_HUMP = MODELS / \"speed_bump.glb\"\n\n# --------------------------------------------------------------- container yard\n# A yard is rows, not a wall. The previous layout quarter-turned every box so\n# its 2.4 m end faced the road, then set them at a 2.5 m pitch from x = -22 to\n# +58: 66 boxes shoulder to shoulder, which from the fixed camera read as a\n# corrugated fence -- and because the only face in shot was a narrow end panel,\n# every container looked taller than it is. This layout is the other reading of\n# the same asset: long sides to the road, two rows 4.75 m apart, real gaps and\n# staggered joints. The shot now shows the 12.1 m side the model was built\n# with, ~13 boxes instead of 66, and the place reads as a depot with depth\n# rather than as a barrier.\nCONTAINER_FRONT_Y = 9.20    # road-side row centre; front face lands on y = 8.0\nCONTAINER_BACK_Y = 13.95    # second row, one bay behind, joints staggered\n# The camera stands on the -Y apron, so everything on that side is seen at a\n# grazing angle and swallows the right half of the frame as bare ground. A\n# second block fills it: same asset, same orientation, but read as a yard block\n# rather than a row -- two staggered lines 4.5 m apart, so the near line hides\n# the far one except through its gaps, which is what gives the side its depth.\n# The near line starts at x = 8 because below ~x = 5 the block falls outside the\n# right edge of the frame: from this camera the apron is only visible from about\n# 30 m ahead, and a container 10.5 m off the kerb only enters the frustum at\n# x ~ 5.\nCONTAINER_APRON_Y = -10.50      # near line, camera side of the road\nCONTAINER_APRON_BACK_Y = -15.00  # far line of the apron block\nCONTAINER_ROWS = {\n    \"front\": CONTAINER_FRONT_Y,\n    \"back\": CONTAINER_BACK_Y,\n    \"apron\": CONTAINER_APRON_Y,\n    \"apron_back\": CONTAINER_APRON_BACK_Y,\n}\nCONTAINER_HEIGHT = 2.90     # the pack's boxes are all 2.9 m tall\n# The pack ships 22 whole 40 ft boxes (12.1 x 2.4 x 2.9) and 15 whole 20 ft\n# ones (6.4 x 2.4 x 2.9); everything else in it is a cut slice. Both lengths\n# are used so the yard is not one repeated box.\n#\n# (x of centre, row, nominal length, base z). A base z of 2.9 means the box is\n# stacked on the one below: the yard stacks two high in the back row only, so\n# the height reads as depth rather than as a wall next to the road.\nCONTAINER_LAYOUT = (\n    (-21.0, \"front\", \"40\", 0.0),\n    (-8.6, \"front\", \"40\", 0.0),\n    (4.2, \"front\", \"40\", 0.0),\n    (17.0, \"front\", \"40\", 0.0),\n    # A 14 m opening instead of a box at x = 29.9: a depot has aisles between\n    # blocks, and this one also lets the back row read through it, which is the\n    # cheapest depth cue in a shot that is otherwise one long wall.\n    (43.2, \"front\", \"40\", 0.0),\n    (56.3, \"front\", \"40\", 0.0),\n    (-14.8, \"back\", \"40\", 0.0),\n    (5.6, \"back\", \"40\", 0.0),\n    (5.6, \"back\", \"40\", CONTAINER_HEIGHT),\n    (24.4, \"back\", \"40\", 0.0),\n    (44.0, \"back\", \"40\", 0.0),\n    (41.0, \"back\", \"20\", CONTAINER_HEIGHT),   # 20 ft on the end of a 40 ft\n    # The apron block: two staggered lines, starting close enough to the camera\n    # that the right-hand ground has something in the foreground. The pitch\n    # wanders between 17 and 21 m on purpose -- an exact bay would read as a\n    # generated row, and this is the side of the shot the eye lands on when it\n    # has nothing else to do. The far line's boxes land in the near line's gaps.\n    (8.0, \"apron\", \"40\", 0.0),\n    (26.0, \"apron\", \"40\", 0.0),\n    (26.0, \"apron\", \"40\", CONTAINER_HEIGHT),\n    (47.0, \"apron\", \"40\", 0.0),\n    (65.0, \"apron\", \"40\", 0.0),\n    (85.0, \"apron\", \"40\", 0.0),\n    (106.0, \"apron\", \"40\", 0.0),\n    (106.0, \"apron\", \"20\", CONTAINER_HEIGHT),\n    (127.0, \"apron\", \"40\", 0.0),\n    (147.0, \"apron\", \"40\", 0.0),\n    (17.0, \"apron_back\", \"40\", 0.0),\n    (37.0, \"apron_back\", \"40\", 0.0),\n    (57.0, \"apron_back\", \"40\", 0.0),\n    (57.0, \"apron_back\", \"40\", CONTAINER_HEIGHT),\n    (78.0, \"apron_back\", \"40\", 0.0),\n    (99.0, \"apron_back\", \"40\", 0.0),\n    (120.0, \"apron_back\", \"40\", 0.0),\n    (141.0, \"apron_back\", \"40\", 0.0),\n)\n\n# How far a box's centre may sit off its row line, in metres. Both yard-side\n# rows are true to within 5 cm: they are set against a kerb. The apron block is\n# the one that is read almost edge-on, and a dead straight line of boxes 10.5 m\n# off the near kerb was the last thing in the shot that still looked generated\n# rather than parked, so those two rows are allowed to wander either way.\n# 1.5 m proved too polite: the two lines held a constant 4.5 m gap, so the eye\n# still read \"two rows\" with a wobble on them. At 2.2 m the near line sets back\n# anywhere from 4.7 m to 8.1 m off the kerb and the far line 9.1 m to 12.7 m,\n# so consecutive boxes step in and out by up to 3.4 m and every bay is at a\n# visibly different distance from the road. The bands still stop just short of\n# each other, so no rear box ever comes forward of a front one.\nROW_DEPTH_JITTER = {\n    \"front\": 0.05,\n    \"back\": 0.05,\n    \"apron\": 2.20,\n    \"apron_back\": 2.20,\n}\n\n# ---------------------------------------------------------------------- lamps\nLAMP_MODEL_HEIGHT = 5.46\nLAMP_TARGET_HEIGHT = 6.40\n# Yard lighting is laid out to light the apron, not to line the kerb. This row\n# has been thinned twice and the lesson from both passes is that pitch is the\n# wrong knob: a 6.4 m mast is still ~34 px tall at 240 m, so the far end of the\n# row never shrinks away -- it just piles up around the vanishing point and the\n# whole line keeps reading as a fence of posts no matter how far apart they\n# stand. At 36 m that pile-up was the complaint, so the row is now *shorter in\n# count* instead: 60 m between masts, 4 of them in shot.\n# The row still has to reach somewhere, though. An earlier version stopped at\n# x = 48 and the masts visibly ran out a third of the way to the horizon, which\n# is the same tell as a road that ends, so the last mast sits at x = 200, past\n# the point where the markings go sub-pixel.\nLAMP_XS = (-40.0, 20.0, 80.0, 140.0, 200.0)\nLAMP_Y = 5.00       # yard side of the kerb, same line the old masts stood on\n# There is deliberately no mast on the apron kerb: the block on that side is\n# read at a grazing angle, so a post in front of it became a foreground stick\n# with nothing to light, and the right-hand ground already has the container\n# block to carry its scale. `build_lamp_posts(arm_toward=+1)` is still able to\n# place one if that side ever needs lighting again.\n# The shot is late afternoon with the sun about 30 degrees up, so the posts are\n# switched off -- which is also what a working yard does. The asset ships with\n# its lens at emission strength 1.0 and the renderer used to hang a 520 W point\n# light under every head, which read as \"who left the lights on at noon\". Set\n# this True (and the caller will light them) for a dusk or night pass.\nLAMPS_LIT = False\n\n# ------------------------------------------------------------------ speed hump\nHUMP_MODEL_HALF_LENGTH = 0.60   # |x| where the model's profile reaches the road\nHUMP_MODEL_PEAK = 0.103\nHUMP_MODEL_HALF_WIDTH = 4.96\nHUMP_MODEL_CENTRE_Y = 3.475\n\n\ndef _import_glb(glb: Path) -> list[bpy.types.Object]:\n    before = set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(glb))\n    return [obj for obj in bpy.data.objects if obj not in before]\n\n\ndef _group(objs: list[bpy.types.Object], name: str) -> bpy.types.Object:\n    \"\"\"Parent the imported roots to a fresh empty without moving anything.\"\"\"\n    root = bpy.data.objects.new(name, None)\n    bpy.context.scene.collection.objects.link(root)\n    members = set(objs)\n    for obj in objs:\n        if obj.parent in members:\n            continue\n        world = obj.matrix_world.copy()\n        obj.parent = root\n        obj.matrix_world = world\n    return root\n\n\ndef _harvest_containers() -> tuple[list[bpy.types.Object], list[bpy.types.Object]]:\n    \"\"\"Import the pack and keep its intact boxes, in world space, split by length.\n\n    63 meshes, but only 37 of them are whole containers -- the rest are cut\n    boxes the pack uses to fill its own scene edges (0.5 x 1.1 x 2.8 m slices).\n    Placing those as if they were containers is what left 1 m gaps in the old\n    row. Returns ``(40 ft, 20 ft)`` so the layout table can pick a length per\n    slot instead of accepting whatever came first.\n    \"\"\"\n    objs = _import_glb(CONTAINER_PACK)\n    meshes = [obj for obj in objs if obj.type == \"MESH\"]\n    empties = [obj for obj in objs if obj.type != \"MESH\"]\n    forties: list[bpy.types.Object] = []\n    twenties: list[bpy.types.Object] = []\n    for obj in meshes:\n        lo, hi = _bbox_world(obj)\n        long_side = max(hi[0] - lo[0], hi[1] - lo[1])\n        if (hi[2] - lo[2]) < 2.0:\n            continue\n        if long_side > 10.0:\n            forties.append(obj)\n        elif long_side > 5.0:\n            twenties.append(obj)\n    keep = set(forties) | set(twenties)\n    for obj in meshes:\n        if obj not in keep:\n            bpy.data.objects.remove(obj, do_unlink=True)\n    for obj in empties:\n        bpy.data.objects.remove(obj, do_unlink=True)\n    for obj in keep:\n        world = obj.matrix_world.copy()\n        obj.parent = None\n        obj.matrix_world = world\n    return forties, twenties\n\n\ndef _bbox_world(obj: bpy.types.Object) -> tuple[list[float], list[float]]:\n    pts = [obj.matrix_world @ v.co for v in obj.data.vertices]\n    return (\n        [min(p[i] for p in pts) for i in range(3)],\n        [max(p[i] for p in pts) for i in range(3)],\n    )\n\n\ndef _yaw_about_centre(obj: bpy.types.Object, angle: float) -> None:\n    \"\"\"Turn ``obj`` about the vertical axis through its own bounding-box centre.\"\"\"\n    lo, hi = _bbox_world(obj)\n    centre = Vector(((lo[0] + hi[0]) * 0.5, (lo[1] + hi[1]) * 0.5, (lo[2] + hi[2]) * 0.5))\n    obj.matrix_world = (\n        Matrix.Translation(centre)\n        @ Matrix.Rotation(angle, 4, \"Z\")\n        @ Matrix.Translation(-centre)\n        @ obj.matrix_world\n    )\n\n\ndef _long_axis_is_x(obj: bpy.types.Object) -> bool:\n    lo, hi = _bbox_world(obj)\n    return (hi[0] - lo[0]) >= (hi[1] - lo[1])\n\n\ndef _place(obj: bpy.types.Object, x: float, y: float, z_base: float) -> tuple[float, float, float]:\n    \"\"\"Sit ``obj`` on ``z_base`` with its bbox centre over ``(x, y)``, long side to the road.\n\n    The layout table is written in road coordinates -- x along the haul road, y\n    away from it -- so a box whose long axis is authored along Y is turned a\n    quarter first. Returns the box's (length, depth, height) after the turn.\n    \"\"\"\n    if not _long_axis_is_x(obj):\n        _yaw_about_centre(obj, math.pi / 2.0)\n    lo, hi = _bbox_world(obj)\n    dims = (hi[0] - lo[0], hi[1] - lo[1], hi[2] - lo[2])\n    obj.matrix_world = (\n        Matrix.Translation(\n            (x - (lo[0] + hi[0]) * 0.5, y - (lo[1] + hi[1]) * 0.5, z_base - lo[2])\n        )\n        @ obj.matrix_world\n    )\n    return dims\n\n\ndef build_cargo_cartons(count: int = 2) -> list[bpy.types.Object]:\n    \"\"\"Import the parcel glb once and clone it for every cargo body.\n\n    The collider is a box of ``CARGO_HALF_EXTENTS``, so the picture only stays\n    honest if the mesh really is that box: the import is scaled by the single\n    factor ``CARGO_SCALE``, its bounding-box centre is moved to the origin, and\n    the transform is baked into the mesh. After that one object is a parcel\n    whose ``location`` is its centre -- the same quantity the simulation reports\n    -- and the clones are ``Object.copy()``, so all bodies share one mesh.\n    \"\"\"\n    asset = MODELS / cfg.CARGO_ASSET\n    imported = _import_glb(asset)\n    meshes = [obj for obj in imported if obj.type == \"MESH\"]\n    if not meshes:\n        raise RuntimeError(f\"{asset.name} imported no mesh\")\n    for obj in imported:\n        if obj.type != \"MESH\":\n            bpy.data.objects.remove(obj, do_unlink=True)\n\n    bpy.ops.object.select_all(action=\"DESELECT\")\n    for obj in meshes:\n        obj.select_set(True)\n    bpy.context.view_layer.objects.active = meshes[0]\n    if len(meshes) > 1:\n        bpy.ops.object.join()\n    proto = meshes[0]\n\n    lo, hi = _bbox_world(proto)\n    centre = Vector(((lo[i] + hi[i]) * 0.5 for i in range(3)))\n    proto.matrix_world = (\n        Matrix.Scale(cfg.CARGO_SCALE, 4) @ Matrix.Translation(-centre) @ proto.matrix_world\n    )\n    bpy.ops.object.select_all(action=\"DESELECT\")\n    proto.select_set(True)\n    bpy.context.view_layer.objects.active = proto\n    bpy.ops.object.transform_apply(location=True, rotation=True, scale=True)\n\n    # Cardboard, not the pack's default: the glb ships a mid-grey that reads as\n    # moulded plastic next to the truck's paint.\n    for slot in proto.material_slots:\n        if slot.material and slot.material.use_nodes:\n            for node in slot.material.node_tree.nodes:\n                if node.type == \"BSDF_PRINCIPLED\":\n                    node.inputs[\"Roughness\"].default_value = 0.82\n                    set_shader_input(node, 'Specular IOR Level', 0.28)\n\n    cartons = [proto]\n    for index in range(1, count):\n        clone = proto.copy()\n        bpy.context.scene.collection.objects.link(clone)\n        cartons.append(clone)\n    for index, obj in enumerate(cartons):\n        obj.name = f\"cargo_{index + 1}\"\n    return cartons\n\n\ndef _bay_hash(row: str, x: float) -> float:\n    \"\"\"Deterministic value in ``[-1, 1]`` for one bay of one row.\n\n    Keyed on ``(row, x)`` rather than on the loop index so a stacked box keeps\n    the placement and the yaw of the box it stands on: an index-keyed value\n    would slide the upper container up to three metres off the lower one.\n    \"\"\"\n    seed = int(round(float(x) * 10.0)) * 7919 + sum(ord(c) for c in row) * 104729\n    return ((seed * 2654435761) % 2003) / 1001.0 - 1.0\n\n\ndef build_container_yard() -> bpy.types.Object:\n    \"\"\"Lay the pack's intact boxes out as two rows behind the fence.\n\n    ``Object.copy()`` shares the mesh datablock, so a box reused twice costs one\n    transform and no geometry; the harvested originals are deleted afterwards so\n    the pack's own depot layout cannot leak into the shot.\n    \"\"\"\n    forties, twenties = _harvest_containers()\n    root = bpy.data.objects.new(\"container_yard\", None)\n    bpy.context.scene.collection.objects.link(root)\n\n    sources = {\"40\": forties, \"20\": twenties}\n    used = {\"40\": 0, \"20\": 0}\n    for index, (x, row, length, z_base) in enumerate(CONTAINER_LAYOUT):\n        pool = sources[length]\n        if not pool:\n            continue\n        source = pool[used[length] % len(pool)]\n        used[length] += 1\n        obj = source.copy()\n        obj.name = f\"container_{row}_{index:02d}\"\n        bpy.context.scene.collection.objects.link(obj)\n\n        # Deterministic jitter: a perfect grid is the loudest generated tell\n        # left, and no RNG keeps the render reproducible. Depth is the one that\n        # matters here -- how far the box sits from its kerb -- see\n        # ``ROW_DEPTH_JITTER``; a degree of yaw is what a box set down by a\n        # crane actually has, and the gaps in the table do the rest.\n        wobble = _bay_hash(row, x)\n        y = CONTAINER_ROWS[row] + wobble * ROW_DEPTH_JITTER[row]\n        _yaw_about_centre(obj, math.radians(wobble * 1.1))\n        _place(obj, x, y, z_base)\n        obj.parent = root\n\n    for obj in forties + twenties:\n        bpy.data.objects.remove(obj, do_unlink=True)\n    return root\n\n\ndef _unlit_lens(objs: list[bpy.types.Object]) -> None:\n    \"\"\"Drop the glb's emissive lamp lens so an unlit post really is unlit.\n\n    The asset authors the lens as white emission at strength 1.0, which in\n    daylight is a glowing panel on every post. Zeroing the strength keeps the\n    lens geometry and its base colour -- it reads as a plastic cover.\n    \"\"\"\n    for obj in objs:\n        if obj.type != \"MESH\":\n            continue\n        for slot in obj.material_slots:\n            mat = slot.material\n            if not mat or not mat.use_nodes:\n                continue\n            bsdf = next(\n                (n for n in mat.node_tree.nodes if n.type == \"BSDF_PRINCIPLED\"), None\n            )\n            if bsdf is None:\n                continue\n            strength = bsdf.inputs.get(\"Emission Strength\")\n            if strength is not None and not strength.is_linked:\n                strength.default_value = 0.0\n\n\ndef build_lamp_posts(\n    xs=LAMP_XS,\n    y: float = LAMP_Y,\n    height: float = LAMP_TARGET_HEIGHT,\n    arm_toward: float = -1.0,\n) -> list[tuple[float, float, float]]:\n    \"\"\"Place the downloaded post along a kerb line.\n\n    The asset's arm reaches +X, so the post is yawed a quarter turn to point it\n    across the road instead of down it. ``arm_toward`` is the *sign of Y* the\n    arm should reach: -1 on the yard kerb, where the road lies at y < 5, and +1\n    on the apron kerb on the camera side, where the road lies at y > -7.6.\n    Yawing both rows the same way is what leaves the apron posts lighting the\n    back of their own block, so the sign is carried through to the head offset\n    the caller hangs its point light on.\n    \"\"\"\n    factor = float(height) / LAMP_MODEL_HEIGHT\n    sign = 1.0 if arm_toward >= 0.0 else -1.0\n    heads: list[tuple[float, float, float]] = []\n    for index, x in enumerate(xs):\n        objs = _import_glb(LAMPPOST)\n        if not LAMPS_LIT:\n            _unlit_lens(objs)\n        root = _group(objs, f\"lamp_post_{index}\")\n        root.location = (float(x), float(y), 0.0)\n        root.rotation_euler = (0.0, 0.0, sign * math.pi / 2.0)\n        root.scale = (factor, factor, factor)\n        heads.append((float(x), float(y) + sign * 1.15 * factor, 5.05 * factor))\n    return heads\n\n\ndef build_speed_hump(\n    height: float, width: float, road_half_width: float\n) -> bpy.types.Object:\n    \"\"\"Skin the collider bump with the downloaded hump.\n\n    Three separate factors, each chosen against the collider rather than the\n    asset:\n\n    * X maps the model's ramp feet (|x| = 0.60) onto the collider's half width,\n      so the hump starts rising exactly where the collision profile does;\n    * Z puts the model's 0.103 m plateau on the requested peak height;\n    * Y spans the visible road width.\n\n    The model's top is flatter than a sine, so mid-slope it sits up to ~26 mm\n    above the collision profile -- the tyre sinks into the hump by that much\n    instead of floating over it, which is the error that reads correctly.\n    \"\"\"\n    objs = _import_glb(SPEED_HUMP)\n    root = _group(objs, \"speed_hump\")\n    root.scale = (\n        (float(width) * 0.5) / HUMP_MODEL_HALF_LENGTH,\n        (2.0 * float(road_half_width)) / (2.0 * HUMP_MODEL_HALF_WIDTH),\n        float(height) / HUMP_MODEL_PEAK,\n    )\n    root.location = (\n        cfg.SPEED_BUMP_CENTER_X,\n        -HUMP_MODEL_CENTRE_Y * root.scale[1],\n        0.0,\n    )\n    return root\n", "flatbed_speed_bump.import_truck": "\"\"\"Adapt the desktop CC-BY truck to the benchmark's chassis/deck rig.\n\nThe glb is a real-proportioned three-axle flatbed authored at 26.03 x 8.87 x\n8.86 model units. It is *not* a 1:1 asset -- it is a real truck blown up to\nroughly 3.4x life size, so every proportion is right and the absolute size is\nnot. This adapter therefore applies exactly one factor to it, ``scale``, on all\nthree axes::\n\n    X = cfg.model_x(p.y)      Y = p.x * scale      Z = cfg.model_z(p.z)\n\n``cfg.TRUCK_SCALE`` is that factor and ``cfg.model_x`` / ``cfg.model_z`` are the\nsame two functions the collision rig is built from, so the visible mesh and the\ncollider cannot disagree -- if the deck plank moves, the box the cargo rests on\nmoves with it. Nothing is stretched along a single axis: an earlier version\ncorbelled the 0.70 m between the model's sill and its bed into one band so the\ndeck could stay at 1.25 m, which is exactly what made the cab read as mounted on\nstilts. The rig follows the model instead, so the deck sits at 0.737 m.\n\nThe one part that is not simply ``scale`` is the tyre: the rig models a single\nwheel radius (``cfg.WHEEL_RADIUS``), which is the front tyre's 1.635 units times\n``scale``. The front tyres therefore land exactly, and the narrower rear tandem\n(1.489 units) is scaled up by 9.8 % so all six tyres can stand on the road. The\nfront axle is the one that strikes the bump, so the contact that matters is\nexact.\n\nMaterials: the glb's paint map is a near-white panel sheet with rust along the\nseams (see ``assets/models/flatbed_unity3d.glb`` image 0), and its paint\nmaterial is glTF ``roughness 0.0`` -- a mirror. The dark olive on the published\npage is that mirror reflecting a dark environment, not a colour in the texture.\nThe tint below reproduces it by multiplying the map, so the grime survives, and\n``PAINT_ROUGHNESS`` makes it read as paint rather than chrome.\n\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nfrom pathlib import Path\n\nimport bpy\nfrom mathutils import Vector\n\nimport scene_support.flatbed_speed_bump.scene_config as cfg\n\nASSET = _PCVE_ROOT / 'assets' / 'models' / 'flatbed_unity3d.glb'\n\n# Multiplied into the paint map: a near-white base with baked rust streaks\n# becomes the dark olive the published model shows, streaks and panel dirt\n# intact.\nPAINT_TINT = (0.30, 0.32, 0.20)\nPAINT_ROUGHNESS = 0.34\nWHEEL_ROUGHNESS = 0.52\n\n\ndef _bbox(points):\n    lo = Vector(tuple(min(p[i] for p in points) for i in range(3)))\n    hi = Vector(tuple(max(p[i] for p in points) for i in range(3)))\n    return lo, hi, (lo + hi) * 0.5\n\n\ndef _tint_base_color(mat, tint) -> None:\n    \"\"\"Multiply ``mat``'s base-colour map by ``tint`` (the map is kept).\"\"\"\n    if not mat or not mat.use_nodes:\n        return\n    nodes = mat.node_tree.nodes\n    links = mat.node_tree.links\n    bsdf = next((n for n in nodes if n.type == 'BSDF_PRINCIPLED'), None)\n    if bsdf is None or not bsdf.inputs['Base Color'].is_linked:\n        return\n    source = bsdf.inputs['Base Color'].links[0].from_socket\n    mix = nodes.new('ShaderNodeMix')\n    mix.name = 'paint_tint'\n    mix.data_type = 'RGBA'\n    mix.blend_type = 'MULTIPLY'\n    mix.clamp_factor = True\n    sockets = {s.identifier: s for s in mix.inputs}\n    factor = sockets.get('Factor_Float') or mix.inputs[0]\n    factor.default_value = 1.0\n    color_a = sockets.get('A_Color') or mix.inputs[6]\n    color_b = sockets.get('B_Color') or mix.inputs[7]\n    color_b.default_value = (tint[0], tint[1], tint[2], 1.0)\n    result = next((s for s in mix.outputs if s.identifier == 'Result_Color'), mix.outputs[2])\n    links.new(source, color_a)\n    links.new(result, bsdf.inputs['Base Color'])\n\n\ndef build_truck(asset=None):\n    source = Path(asset) if asset else ASSET\n    if not source.is_file():\n        raise FileNotFoundError(f\"Required truck model not found: {source}\")\n    bpy.ops.import_scene.gltf(filepath=str(source))\n    imported = list(bpy.context.selected_objects)\n    bpy.context.view_layer.update()\n    meshes = [o for o in imported if o.type == 'MESH']\n    baked = [(o, [o.matrix_world @ v.co for v in o.data.vertices]) for o in meshes]\n    for o in meshes:\n        o.parent = None\n        o.matrix_world.identity()\n    for o in imported:\n        if o.type != 'MESH':\n            bpy.data.objects.remove(o, do_unlink=True)\n\n    # --- wheel inventory: axle positions drive every later anchor ----------\n    wheel_info = {}\n    for obj, points in baked:\n        if 'Wheel' in obj.name and points:\n            lo, hi, centre = _bbox(points)\n            wheel_info[obj.name] = (lo, hi, centre)\n    front = [c.y for n, (_lo, _hi, c) in wheel_info.items() if 'F_Wheel' in n]\n    rear = [c.y for n, (_lo, _hi, c) in wheel_info.items() if 'F_Wheel' not in n]\n    if not front or not rear:\n        raise RuntimeError('flatbed glb: expected front and rear wheels by name')\n\n    scale = cfg.TRUCK_SCALE\n    # The rig's axle spacing is ``scale`` times the model's by construction;\n    # check it here so a swapped asset fails loudly instead of importing with a\n    # silently wrong wheelbase.\n    model_spread = abs(sum(front) / len(front) - sum(rear) / len(rear))\n    if abs(model_spread * scale - cfg.WHEEL_BASE) > 1e-3:\n        raise RuntimeError(\n            f'flatbed glb: axle spread {model_spread:.4f} x {scale:.6f} = '\n            f'{model_spread * scale:.4f} m, rig has {cfg.WHEEL_BASE:.4f} m'\n        )\n\n    def to_vehicle(p: Vector) -> Vector:\n        \"\"\"Model units -> vehicle frame (road at -R, axle line at 0, nose +X).\"\"\"\n        return Vector((\n            cfg.model_x(p.y),\n            p.x * scale,\n            cfg.model_z(p.z),\n        ))\n\n    chassis = bpy.data.objects.new('truck_chassis', None)\n    deck = bpy.data.objects.new('truck_deck', None)\n    bpy.context.collection.objects.link(chassis)\n    bpy.context.collection.objects.link(deck)\n\n    wheels = []\n    for obj, points in baked:\n        if obj.name in wheel_info:\n            lo, hi, centre = wheel_info[obj.name]\n            # The rig has one wheel radius; the front tyre is the exact one, the\n            # rear tandem is 9.8 % larger (see the module docstring).\n            wheel_scale = cfg.WHEEL_RADIUS / ((hi.z - lo.z) * 0.5)\n            radius = (hi.z - lo.z) * 0.5 * wheel_scale\n            position = to_vehicle(centre)\n            pivot = bpy.data.objects.new(obj.name + '_axle', None)\n            bpy.context.collection.objects.link(pivot)\n            pivot.parent = chassis\n            # The tyre has to meet the road: its centre goes on the physics axle\n            # line, not where the body warp would have put it.\n            pivot.location = (position.x, position.y, -cfg.CHASSIS_COM_Z)\n            pivot['rolling_radius'] = radius\n            obj.parent = pivot\n            for v, p in zip(obj.data.vertices, points):\n                q = p - centre\n                # The model's axle runs along X; the pivot spins about its own Y.\n                v.co = (-q.y * wheel_scale, q.x * wheel_scale, q.z * wheel_scale)\n            wheels.append(pivot)\n        else:\n            obj.parent = chassis\n            for v, p in zip(obj.data.vertices, points):\n                vehicle = to_vehicle(p)\n                v.co = (vehicle.x, vehicle.y, vehicle.z - cfg.CHASSIS_COM_Z)\n            # Split the bed from the cab so the original suspension still works.\n            # Faces behind the cab and above the sill belong to the bed.\n            bed_faces = [poly.index for poly in obj.data.polygons if all(\n                points[i].y > cfg.MODEL_BED_FRONT_Y and points[i].z > cfg.MODEL_BED_SILL_Z\n                for i in poly.vertices)]\n            if bed_faces:\n                bpy.ops.object.select_all(action='DESELECT')\n                obj.select_set(True)\n                bpy.context.view_layer.objects.active = obj\n                bpy.ops.object.mode_set(mode='EDIT')\n                bpy.ops.mesh.select_all(action='DESELECT')\n                bpy.ops.object.mode_set(mode='OBJECT')\n                for index in bed_faces:\n                    obj.data.polygons[index].select = True\n                bpy.ops.object.mode_set(mode='EDIT')\n                bpy.ops.mesh.separate(type='SELECTED')\n                bpy.ops.object.mode_set(mode='OBJECT')\n                for part in list(bpy.context.selected_objects):\n                    if part != obj:\n                        part.name = 'imported_sprung_' + part.name\n                        part.parent = deck\n                        for v in part.data.vertices:\n                            v.co -= Vector((\n                                cfg.DECK_CENTER_X, 0,\n                                cfg.DECK_Z - cfg.CHASSIS_COM_Z,\n                            ))\n        for mat in obj.data.materials:\n            if mat and mat.use_nodes:\n                bsdf = next((n for n in mat.node_tree.nodes\n                             if n.type == 'BSDF_PRINCIPLED'), None)\n                if bsdf is None:\n                    continue\n                if 'Paint' in mat.name:\n                    bsdf.inputs['Roughness'].default_value = PAINT_ROUGHNESS\n                    _tint_base_color(mat, PAINT_TINT)\n                elif 'Wheel' in mat.name:\n                    bsdf.inputs['Roughness'].default_value = WHEEL_ROUGHNESS\n                else:\n                    bsdf.inputs['Roughness'].default_value = 0.40\n    return chassis, deck, wheels\n", "flatbed_speed_bump.runtime_support": "\"\"\"Local runtime discovery; scripts also work in ordinary Python/Blender installs.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport os\nimport sys\nfrom pathlib import Path\n\nROOT = _PCVE_ROOT\n_dll_handles = []\nif os.name == \"nt\":\n    directory = Path(sys.prefix) / \"Library/bin\"\n    if directory.exists():\n        _dll_handles.append(os.add_dll_directory(str(directory)))\n\n\ndef python_for(role):\n    sys.path.insert(0, str(ROOT/'clean_scripts'))\n    from pcve_scene_runtime import python_for as resolve_python\n    return resolve_python(role)\n", "flatbed_speed_bump.scene_config": "\"\"\"Shared geometry and baseline parameters for the flatbed-speed-bump scene.\n\nBoth the PyBullet simulation and the Blender renderer import these constants so\nthe collision shapes and the visible meshes cannot drift apart, and so the\nscene's three exposed controls have exactly one definition.\n\nWorld conventions\n-----------------\n* The truck is driven along world **+X**; the cab faces +X.\n* **+Y** is the far kerb (the freight-yard side); **-Y** is the near kerb\n  (safety fence, cones) that faces the camera.\n* Everything about the truck is expressed in the **vehicle reference frame\n  V**: the origin sits on the wheel-axle line at mid-wheelbase, i.e.\n  ``WHEEL_RADIUS`` above the road, so ``V z = 0`` is the axle height and the\n  road surface is at ``V z = -WHEEL_RADIUS``. Chassis-local coordinates are\n  V-relative values shifted by ``-CHASSIS_COM_Z``, because a multibody's base\n  position *is* its centre of mass.\n\nWhy the bed is its own body\n---------------------------\nA rigid truck that clears a speed bump flies as one piece, and so does\nanything resting on it: while the vehicle is ballistic the bed and its cargo\nshare exactly the same acceleration, so the cargo can never leave the bed no\nmatter how violent the jump looks. Making the deck a *sprung* body on a\nprismatic suspension is what actually throws the cargo: the deck overshoots the\nchassis and can be pulled down at well over 1 g on the rebound, which is the\none condition under which a loose carton separates from it.\n\"\"\"\n\nfrom __future__ import annotations\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\n# --------------------------------------------------------------------- truck\n#\n# The rig is *derived from* the asset, not fitted to it. ``flatbed_unity3d.glb``\n# is a real-proportioned three-axle flatbed authored at 26.03 x 8.87 x 8.86\n# model units, and it is placed by ONE factor, ``TRUCK_SCALE``, applied to every\n# vertex on all three axes -- ``model_x`` / ``model_z`` below plus\n# ``p.x * TRUCK_SCALE`` are the whole mapping, and ``import_truck`` calls the\n# same two functions. There is no per-axis correction left anywhere, so every\n# proportion the artist built survives.\n#\n# That is why the deck sits at 0.737 m and the wheelbase is 3.068 m instead of\n# at round numbers: those are where this truck's bed and axles actually are. Any\n# rig that wants the deck higher has to stretch the 0.70 m between the sill and\n# the bed, and that stretch is exactly what reads as \"the cab is on stilts\".\n#\n# The factor itself is the front tyre radius over the rig's, which keeps the\n# 0.34 m wheel: the 0.17 m bump therefore stays at half a wheel radius and the\n# suspension keeps being excited in the band it was tuned for.\n\n# Measured on the asset, in model units (_dump_truck_dimensions.py prints them).\nMODEL_GROUND_Z = -4.43          # tyre contact plane\nMODEL_WHEEL_R = 1.635           # front tyre radius\nMODEL_FRONT_AXLE_Y = -11.2425\nMODEL_REAR_AXLE_Y = 3.5119      # mean of the rear tandem\nMODEL_BED_TOP_Z = -0.887        # up-facing deck plank, level with the tyre tops\nMODEL_BED_FRONT_Y = -6.46       # nose end of the deck, where the cab ends\nMODEL_BED_SILL_Z = -1.23        # lowest bed face; below this it is still frame\nMODEL_BED_Y = (-6.45, 9.64)\nMODEL_BED_X = (-4.11, 4.09)\nMODEL_CAB_Y = (-16.39, -6.51)\nMODEL_CAB_X = (-4.46, 4.41)\nMODEL_CAB_Z = (-1.23, 4.43)\nMODEL_FRAME_Y = (-15.75, 9.57)\nMODEL_FRAME_X = (-4.15, 4.13)\n\nTRUCK_SCALE = 0.34 / MODEL_WHEEL_R                    # 0.2079511\n\nWHEEL_RADIUS = MODEL_WHEEL_R * TRUCK_SCALE            # 0.3400\nWHEEL_WIDTH = 1.437 * TRUCK_SCALE                     # 0.2988, front tyre\nWHEEL_BASE = (MODEL_REAR_AXLE_Y - MODEL_FRONT_AXLE_Y) * TRUCK_SCALE\nWHEEL_XS = (-0.5 * WHEEL_BASE, 0.5 * WHEEL_BASE)      # 3.0682 m axle spacing\n# The front axle strikes the bump first, so its track is what the four collision\n# cylinders use; the rear tandem is narrower (0.591 m half-track) and only its\n# visible wheels sit there.\nWHEEL_YS = (-3.398 * TRUCK_SCALE, 3.398 * TRUCK_SCALE)  # 1.4132 m track\n\n\ndef model_x(y: float) -> float:\n    \"\"\"Model +Y (rearwards) -> vehicle X, front axle on ``+WHEEL_BASE / 2``.\"\"\"\n    return 0.5 * WHEEL_BASE - (y - MODEL_FRONT_AXLE_Y) * TRUCK_SCALE\n\n\ndef model_z(z: float) -> float:\n    \"\"\"Model +Z -> vehicle Z, with the tyre contact patch landing on ``-R``.\"\"\"\n    return -WHEEL_RADIUS + (z - MODEL_GROUND_Z) * TRUCK_SCALE\n\n\n# The chassis body's origin is its centre of mass, placed this high above the\n# ground contact line; the collision shapes below are offset from it. 0.55 m is\n# the height the pitch and roll response was tuned at, and the tyre radius is\n# unchanged, so it stays.\nCHASSIS_MASS = 900.0\nCHASSIS_COM_Z = 0.55\n# Underbody rail, cut off at the axle line. The model's sill reaches down to\n# 0.108 m above the road, which is below the 0.17 m bump crest -- a collider\n# that deep would ride up on the bump, so the box stops at V z = 0. The sim\n# centres this box on X = 0 while the model's own rail is 0.16 m off-centre, so\n# it takes the shorter side: that keeps it inside the body at both ends.\nFRAME_HALF = (\n    min(abs(model_x(MODEL_FRAME_Y[0])), abs(model_x(MODEL_FRAME_Y[1]))),\n    0.5 * (MODEL_FRAME_X[1] - MODEL_FRAME_X[0]) * TRUCK_SCALE,\n    0.125,\n)\nFRAME_Z = 0.125\n# The cab's collision box starts behind the deck's front edge only if it is\n# pushed far enough forward: an overlapping box would press on the deck and\n# lock the suspension solid at zero travel. Here the model's own gap (12 mm) is\n# what separates them; the joint is prismatic in Z, so the deck cannot rotate\n# into the cab.\nCAB_HALF = (\n    abs(0.5 * (model_x(MODEL_CAB_Y[1]) - model_x(MODEL_CAB_Y[0]))),\n    0.5 * (MODEL_CAB_X[1] - MODEL_CAB_X[0]) * TRUCK_SCALE,\n    0.5 * (model_z(MODEL_CAB_Z[1]) - model_z(MODEL_CAB_Z[0])),\n)\nCAB_X = 0.5 * (model_x(MODEL_CAB_Y[1]) + model_x(MODEL_CAB_Y[0]))\nCAB_Z = 0.5 * (model_z(MODEL_CAB_Z[1]) + model_z(MODEL_CAB_Z[0]))\n\n# ------------------------------------------------------- sprung flatbed deck\n\nBED_MASS = 350.0\nDECK_HALF = (\n    abs(0.5 * (model_x(MODEL_BED_Y[1]) - model_x(MODEL_BED_Y[0]))),\n    0.5 * (MODEL_BED_X[1] - MODEL_BED_X[0]) * TRUCK_SCALE,\n    # A 50 mm plate: thin enough to hide inside the model's bed slab, which is\n    # 0.071 m thick at this scale, so the 0.05 m of collision below the plank\n    # surface never pokes out under the visible sill.\n    0.025,\n)\nDECK_CENTER_X = 0.5 * (model_x(MODEL_BED_Y[1]) + model_x(MODEL_BED_Y[0]))\nDECK_TOP_Z = model_z(MODEL_BED_TOP_Z)     # V-frame deck surface, 0.3968\nDECK_Z = DECK_TOP_Z - DECK_HALF[2]        # V-frame centre of the deck at rest\nDECK_FRONT_X = DECK_CENTER_X + DECK_HALF[0]\nDECK_REAR_X = DECK_CENTER_X - DECK_HALF[0]\n\n# Prismatic travel of the deck on the chassis: down is compression, up is droop.\n# Down is capped by the 0.097 m between the deck plate and the frame top.\nSUSPENSION_TRAVEL_DOWN = 0.09\nSUSPENSION_TRAVEL_UP = 0.07\n# 40 kN/m on the 350 kg deck is 1.70 Hz. That is far softer than the 280 kN/m\n# the 2.28 m rig used, and it has to be: what a chassis feeds the deck is the\n# gap between the two axles clearing the bump, and this wheelbase is 3.068 m\n# rather than 2.28 m, i.e. 2.9 Hz instead of 3.9 Hz. A deck stiff enough to\n# follow the chassis over the bump just rides with it, and then the cargo shares\n# its acceleration and never leaves the planks. `_sweep_suspension.py` over\n# 40-280 kN/m x damping ratio 0.12/0.25/0.35 put the launch peak here: 65 mm of\n# deck clearance and 7 airborne frames, against 40 mm and 3 at 280 kN/m.\nSUSPENSION_STIFFNESS = 40_000.0\nSUSPENSION_DAMPING = 1_870.0\n# Bump and droop stops: a stiffer one-sided spring takes over past the travel\n# limits, which is what keeps the deck from driving into the frame.\nSTOP_STIFFNESS = 700_000.0\nSTOP_DAMPING = 6_000.0\n# Hard cap on what the suspension may transmit, as a multiple of the deck's\n# weight. This is what keeps the explicit integration stable when the chassis\n# lands hard: uncapped, a 0.16 m bump sent the deck's travel into the tens of\n# metres.\nSUSPENSION_FORCE_LIMIT_UP = 14.0\nSUSPENSION_FORCE_LIMIT_DOWN = 4.0\n\nCHASSIS_ANGULAR_DAMPING = 0.12\n# The wheels are cylinders fixed to the chassis; they have no axle of their own\n# and cannot spin, so any real Coulomb coefficient turns them into skids that\n# stop the truck (about 0.96 g) long before it reaches the bump. Giving them a\n# near-frictionless contact is what a free-rolling tyre actually looks like\n# here: it still carries the full normal load, so the bump still kicks the\n# truck, it just does not drag.\nWHEEL_ROAD_FRICTION = 0.02\n# Cruise control, as a real force applied at the chassis centre of mass rather\n# than a velocity override. The override was the one thing that made this scene\n# unphysical: resetting the linear velocity every substep threw away the contact\n# impulse's linear part while keeping its angular part, which pumped angular\n# momentum into the chassis and stood the truck on its tail -- an 87 degree\n# wheelie on bumps as small as 0.10 m. A force at the centre of mass cannot\n# torque the chassis, so the pitch it produces is only what the bump really\n# produces.\nDRIVE_FORCE_GAIN = 200_000.0       # N per m/s of speed error\nDRIVE_FORCE_MAX = 25_000.0         # N, about 18 m/s^2 on the laden truck\n\n# ------------------------------------------------------------------- cargo\n# Two identical parcels ride loose on the bed, abreast and almost touching:\n# side by side across the deck, parallel to its long axis, 8 mm apart. The gap\n# is not decorative -- spawning them truly coincident makes Bullet fire a\n# separation impulse on frame 1 -- but it is small enough that the pair reads as\n# one tidy load instead of two boxes parked at random.\n#\n# The parcel is the ``carton_box_05_closed`` glb, measured at 31.5488 x 39.9721\n# x 25.8244 model units with its base on z = 0 (see ``_dump_asset_bounds.py``).\n# One factor takes that to a real parcel: CARGO_SCALE puts the 25.82 height at\n# 0.52 m -- the height the old procedural crate had, so the suspension tuning\n# and the 0.20 friction band still describe the same load. x and y are *not*\n# chosen, they follow the model's own 1.222 : 1.548 : 1 aspect, which is why\n# the footprint comes out 0.635 x 0.805 instead of the old 0.64 x 0.56.\n\nCARGO_ASSET = \"carton_box_05_closed.glb\"\nCARGO_MODEL_SIZE = (31.5488, 39.9721, 25.8244)\nCARGO_TARGET_HEIGHT = 0.52\nCARGO_SCALE = CARGO_TARGET_HEIGHT / CARGO_MODEL_SIZE[2]          # 0.0201362\nCARGO_SIZE = tuple(size * CARGO_SCALE for size in CARGO_MODEL_SIZE)\n\nCARGO_HALF_EXTENTS = (\n    tuple(0.5 * size for size in CARGO_SIZE),                    # 0.3176 x 0.4024 x 0.26\n    tuple(0.5 * size for size in CARGO_SIZE),\n)\n# The pair is abreast in Y but staggered in X by 0.90 m, and the near-side\n# parcel (index 0, -Y, the camera side) is the one set back: its rear face is\n# 0.65 m from the tail edge of the planks, and its centre of mass is 0.97 m\n# from it. That is the whole point of the scene now. The deck lags the chassis\n# on the rebound and the loose parcel lags the deck, so in deck coordinates it\n# travels aft during the strike; mid-deck that aft travel is all spent sliding\n# on the planks, and moving the pair to the tail converts the same aft travel\n# into a parcel going over the back edge while the far parcel rides it out as\n# the control.\n#\n# Both numbers are measured, not chosen, and `_probe_cargo_xs.py` is the\n# measurement: it walks one parcel at a time and reports whether it is still\n# aboard at t = 4 s. The aft slip is 1.0-1.5 m in deck coordinates, so a parcel\n# has to start within ~1.0 m of the tail edge to go over, and the other has to\n# start at least ~1.85 m from it to survive -- which is why the two cannot sit\n# at the same x and why the stagger is 0.9 m rather than the \"just slightly\n# back\" a still frame would suggest. At this split the near parcel leaves at\n# the 9 m/s baseline and still leaves at 7 m/s; the far one does not leave at\n# either, which is what makes the shot readable: one parcel on the road, one\n# still on the planks.\nCARGO_DECK_LOCAL_XS = (-0.70, 0.20)    # deck-local x; -X is aft, 0 = deck centre\nCARGO_GAP_Y = 0.008                     # mm-scale only: see the note above\nCARGO_LOCAL_XS = tuple(DECK_CENTER_X + x for x in CARGO_DECK_LOCAL_XS)\nCARGO_LOCAL_YS = (\n    -(CARGO_HALF_EXTENTS[0][1] + 0.5 * CARGO_GAP_Y),   # near kerb, set back\n    +(CARGO_HALF_EXTENTS[0][1] + 0.5 * CARGO_GAP_Y),   # far kerb, forward\n)\n\n# --------------------------------------------------------------- speed bump\n# A rounded (sine-profile) bump spanning the full road width. Its width stays\n# below the truck's wheelbase, so the two axles strike it separately and the\n# bed is pitched as well as heaved.\n\nSPEED_BUMP_CENTER_X = 0.0\nSPEED_BUMP_WIDTH = 1.34\nSPEED_BUMP_SEGMENTS = 24\n\n# ------------------------------------------------------------------- roadway\n\nROAD_HALF_LENGTH = 70.0\nROAD_HALF_WIDTH = 4.0\nROAD_SURFACE_Z = 0.0\n\n# Truck spawn: far enough back that the approach, the strike, the flight and\n# the landing all fit inside one short clip.\nTRUCK_START_X = -7.0\n\n# ---------------------------------------------------------------- baseline\n\n# The three controls the benchmark exposes, plus the surfaces that are\n# deliberately fixed so a single-variable edit really is single-variable.\nBASELINE_PHYSICS = {\n    \"truck_speed\": 9.0,          # m/s -- about 32 km/h, deliberately too fast\n    \"speed_bump_height\": 0.17,   # m   -- peak height of the rounded bump\n    # 0.20 sits in the middle of the band that matters: below it the cartons\n    # skid off the deck, above it they grip and stay, so both directions of the\n    # edit read as different outcomes. At 0.34 the high side had already\n    # saturated.\n    \"cargo_friction\": 0.20,      # --  cargo box <-> deck pair friction\n}\nFIXED_PHYSICS = {\n    \"deck_friction\": 0.70,       # the deck's own coefficient; the pair with the\n                                 # cargo is what the exposed knob scales\n    \"road_friction\": 0.96,\n    \"cargo_mass\": 42.0,\n    \"gravity_z\": -9.8,\n}\n\n# The camera is a fixed vantage on the near-kerb side of the road, so the truck\n# drives through the frame instead of the frame driving with it. A chase rig\n# would hold the truck still on screen and read the throw only as background\n# motion, which hides the one thing the scene exists to show. It sits on the -Y\n# (camera-facing) side and is framed *left*: the start of the run (the truck\n# intact at x = -7) must be fully in frame, and only the stretch the truck needs\n# to clear the bump matters -- the empty haul road past the landing is left out\n# of shot, so no dead runway dominates the right half of the frame.\nSTATIC_CAMERA_LOCATION = (0.0, -12.0, 3.3)\nSTATIC_CAMERA_TARGET = (1.0, 0.0, 1.15)\nSTATIC_CAMERA_LENS_MM = 26.0\n\nBASELINE_RENDER = {\n    \"fps\": 24,\n    \"duration_sec\": 4.0,\n    # Matches the other rigid-body suites in this repo. EEVEE Next holds about\n    # 14 s per frame here at 960x540/32, so a full clip is roughly 18 minutes;\n    # 1280x720/48 is about three times that for no visible gain.\n    \"resolution\": (960, 540),\n    \"samples\": 32,\n    # The clip is a bolted-down camera by requirement, so it has to hold a run\n    # of 41 m: see ``render_flatbed_speed_bump.CAMERA_PRESETS``. ``static`` only\n    # works for one still.\n    \"camera_mode\": \"clip4s\",\n}\n\n# ------------------------------------------------------------------ helpers\n\n\ndef bed_rest_top_z() -> float:\n    \"\"\"World z of the deck surface with the truck sitting at rest.\"\"\"\n    return WHEEL_RADIUS + DECK_TOP_Z\n\n\ndef road_length_for(speed: float, duration_sec: float, *, margin: float = 12.0) -> float:\n    \"\"\"Half-length that keeps a truck at ``speed`` on the slab for the clip.\"\"\"\n    reach = abs(float(TRUCK_START_X)) + abs(float(speed)) * float(duration_sec) + margin\n    return max(ROAD_HALF_LENGTH, reach)\n", "flatbed_speed_bump": "\"\"\"Shared support modules for flatbed_speed_bump.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n"}""")

_BUNDLE_SCENE_ALIAS = 'flatbed_speed_bump'
_BUNDLE_ALIASES = ['cache_contract', 'import_props', 'import_truck', 'runtime_support', 'scene_config', 'flatbed_speed_bump', 'flatbed_speed_bump.cache_contract', 'flatbed_speed_bump.import_props', 'flatbed_speed_bump.import_truck', 'flatbed_speed_bump.runtime_support', 'flatbed_speed_bump.scene_config']

class _SceneBundleLoader(_bundle_abc.MetaPathFinder, _bundle_abc.Loader):
    def find_spec(self, fullname, path=None, target=None):
        if fullname not in _BUNDLE_SOURCES:
            return None
        package = (fullname == "scene_support" or fullname.count(".") == 1 and fullname.startswith("scene_support.") or fullname == _BUNDLE_SCENE_ALIAS)
        return _bundle_util.spec_from_loader(fullname, self, is_package=package)

    def create_module(self, spec):
        return None

    def exec_module(self, module):
        name = module.__spec__.name
        package = module.__spec__.submodule_search_locations is not None
        if name == "scene_support":
            origin = _BUNDLE_SCENE / "scene_support" / "__init__.py"
        elif name == _BUNDLE_SCENE_ALIAS:
            origin = _BUNDLE_SCENE / "scene_support" / name / "__init__.py"
        elif name.startswith(_BUNDLE_SCENE_ALIAS + "."):
            origin = _BUNDLE_SCENE / "scene_support" / name.replace(".", "/")
            origin = origin.with_suffix(".py")
        elif name.startswith("scene_support."):
            tail = name.split(".", 1)[1]
            if package:
                origin = _BUNDLE_SCENE / "scene_support" / tail / "__init__.py"
            else:
                origin = _BUNDLE_SCENE / "scene_support" / tail.replace(".", "/")
                origin = origin.with_suffix(".py")
        else:
            origin = _BUNDLE_SCRIPTS / (name + ".py")
        module.__file__ = str(origin)
        module.__package__ = name if package else (_BUNDLE_SCENE_ALIAS if name.startswith(_BUNDLE_SCENE_ALIAS + ".") or name in ['cache_contract', 'import_props', 'import_truck', 'runtime_support', 'scene_config'] else name.rpartition("." )[0])
        if package:
            module.__path__ = [str(_BUNDLE_SCENE)] if name == _BUNDLE_SCENE_ALIAS else []
        source = _BUNDLE_SOURCES[name]
        exec(compile(source, str(origin), "exec"), module.__dict__)

def install_scene_support():
    if not any(isinstance(item, _SceneBundleLoader) for item in _bundle_sys.meta_path):
        _bundle_sys.meta_path.insert(0, _SceneBundleLoader())

install_scene_support()




